/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({prompt,answer,options:[answer,wrong1,wrong2],explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>{const senseMap={manuscript:[1,2,1,2],many:[1,2,3,1],map:[1,2,3,4],mar:[1,1,2,1],marathon:[1,2,3,1],marble:[1,2,3,1],March:[1,2,2,1],margin:[1,2,3,4],marginal:[1,2,1,2],marginally:[1,2,1,2],marine:[1,2,3,1],marital:[1,2,1,2],maritime:[1,2,1,2],mark:[1,2,3,4],market:[1,2,3,2],marketing:[1,2,2,1],marrow:[1,2,2,1],marry:[1,2,3,1],marsh:[1,2,1,1],marshal:[1,2,3,3],marsupial:[1,2,1,2],martyr:[1,2,3,1],marvel:[1,2,1,2],marvelous:[1,2,1,1],Marxism:[1,2,2,1],Marxist:[1,2,1,2],masculine:[1,2,2,2],mask:[1,2,3,3],mason:[1,2,1,2],mass:[1,2,3,4],massacre:[1,2,1,2],massage:[1,2,3,3],massif:[1,2,1,2],mast:[1,2,1,2],master:[1,2,4,5],masterful:[1,2,1,2],masterly:[1,2,1,1],masterpiece:[1,2,2,1],masthead:[1,1,2,1],mat:[1,2,3,2],match:[1,2,3,4],matching:[1,2,2,1],matchless:[1,2,1,2]};return D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((q,i)=>({...q,id:w+'.q'+(i+1),senseId:w+'.s'+(senseMap[w]?.[i]||1),type:'辨义与用法'}))});};
P('manuscript','Manuscript comes from Latin manu scriptus, “written by hand,” and names an unpublished text or an old hand-written document.',[C('manuscript.s1','出版编辑','The editor returned the manuscript with notes in the margin before the author sent it to the publisher.','作者把稿件送交出版商前，编辑将带有页边批注的手稿退了回来。','The editor returned the manuscript / with notes in the margin / before the author / sent it to the publisher.','manuscript.s1 指出版前的书稿或投稿原稿；with 引出编辑批注。','文本仍在编辑阶段，尚未出版，符合 s1。'),C('manuscript.s2','历史档案','Researchers examined a fragile medieval manuscript written by hand on parchment.','研究人员查阅了一份写在羊皮纸上的易损中世纪手抄本。','Researchers examined / a fragile medieval manuscript / written by hand / on parchment.','历史文献语境中 manuscript 指手写的古代文书或抄本。','手写在羊皮纸上的中世纪文献符合 s2。')],M('The editor called the printed bestseller a manuscript even though it had already been published in thousands of copies.','The editor called the unpublished draft a manuscript before it went to print.','已经大量出版的成书不是这里所指的出版前原稿。'),[Q('An author’s manuscript is usually?','a text before publication','a finished printed bestseller in every shop','a map of a river','manuscript 常指出版前的书稿。'),Q('A medieval manuscript may be?','an old document written by hand','a modern loudspeaker','a glass marble','历史语境中 manuscript 指手写文献。'),Q('What did the editor add?','notes in the margin','a new roof over the book','a marathon route','编辑在稿件边缘写下了批注。'),Q('The Latin elements in manuscript mean?','written by hand','many pages of stone','a book without a cover','manu scriptus 的字面义是“手写的”。','word-formation')]);
P('many','Many comes from Old English manig and is a determiner before plural nouns, a pronoun meaning many people or things, or part of as/so/too many.',[C('many.s1','调查人数','Many residents signed the petition after the council announced plans to close the local library.','市政委员会宣布计划关闭当地图书馆后，许多居民在请愿书上签了名。','Many residents signed the petition / after the council announced / plans to close the local library.','many 作限定词，置于复数可数名词 residents 前。','签名居民数量较多，符合 s1。'),C('many.s2','已知群体','Some volunteers had finished early, but many stayed to pack the remaining boxes.','一些志愿者提前完成了，但许多人留下来打包剩余的箱子。','Some volunteers had finished early / but many stayed / to pack the remaining boxes.','many 可独立作代词，代替语境中已知的复数名词。','many 指前句提及的 volunteers，符合 s2。'),C('many.s3','数量程度','There were too many forms to complete before the office closed at five.','办公室五点关门前，要填的表格实在太多了。','There were too many forms / to complete / before the office closed / at five.','too many + 复数可数名词表示数量过多。','表格数量超过可及时完成的程度。')],M('Many resident signed the petition after the meeting.','Many residents signed the petition after the meeting.','many 作限定词修饰可数名词时，名词应用复数。','grammar'),[Q('In “many residents,” many is followed by?','a plural count noun','an uncountable verb','a singular adjective only','many residents 中 residents 用复数。','grammar'),Q('In “many stayed,” many stands for?','many volunteers already mentioned','one person never introduced','a large amount of water','many 可独立代替前文提到的复数人或物。'),Q('“Too many forms” means?','more forms than can conveniently be handled','exactly one form','no forms at all','too many 表示数量过多。'),Q('Which phrase is grammatical?','many people','many person','many of person','many 直接修饰可数名词复数。','grammar')]);
P('many-sided','Many-sided combines many and sided and describes a person or issue with numerous aspects, abilities, or viewpoints.',C('many-sided.s1','人物简介','The biography presents a many-sided artist who painted, composed music, and designed public buildings.','这本传记呈现了一位多才多面的艺术家，他既绘画、作曲，也设计公共建筑。','The biography presents / a many-sided artist / who painted, composed music, / and designed public buildings.','many-sided 作复合形容词修饰 artist，many sides 指多个方面或才能。','人物在多个领域创作，体现多面性。'),M('The article called the artist many-sided because she had only one skill and never explored another field.','The article called the artist many-sided because she worked successfully in several different fields.','只拥有一种技能不足以支持“多方面”的评价。'),[Q('A many-sided artist has?','abilities or interests in several areas','exactly one skill','a physical map with many folds','many-sided 描写多才或多面的特征。'),Q('Which person is many-sided?','a designer who also writes music and paints','a worker who performs one repeated task only','a person with a single viewpoint','跨绘画、音乐和设计的人才是多方面的。'),Q('The biography describes what kind of artist?','one working in several fields','one who never creates anything','one who only studies maps','传记提及她在多个领域创作。'),Q('Many-sided is formed from?','many + sided','mar + ital','map + able','该复合形容词由 many 与 sided 构成。','word-formation')]);
P('map','Map is related to medieval Latin mappa (“cloth, chart”); it names a representation of places or systems and can also mean to chart or plan.',[C('map.s1','城市导航','The map showed a footpath from the station to the museum, so we avoided the busy main road.','地图标出了从车站到博物馆的人行小路，因此我们避开了繁忙的主干道。','The map showed / a footpath from the station to the museum / so we avoided / the busy main road.','map 作可数名词，show 引出地图提供的信息。','它用图示表示道路位置，符合 s1。'),C('map.s2','科学图谱','The researchers compared a brain map showing active regions with scans from the previous experiment.','研究人员把显示活跃区域的大脑图谱与上次实验的扫描结果作了比较。','The researchers compared / a brain map showing active regions / with scans / from the previous experiment.','map 可指系统中各部分布局关系的图谱，brain map 属此类。','图谱呈现大脑各区域的排列和活动信息。'),C('map.s3','测绘海岸','Surveyors mapped the newly exposed coastline before construction crews entered the area.','施工队进入该区域前，测绘员绘制了新显露海岸线的地图。','Surveyors mapped / the newly exposed coastline / before construction crews / entered the area.','map 作及物动词，表示测绘或绘制某区域的地图。','测绘员记录海岸地形，符合动词义 s3。'),C('map.s4','行动规划','The project lead mapped out each stage of the relocation before announcing the schedule to staff.','项目负责人在向员工公布日程前，详细规划了搬迁的每个阶段。','The project lead mapped out / each stage of the relocation / before announcing / the schedule to staff.','map out something 表示逐步规划或安排。','先安排各步骤再公布日程，符合 s4。')],M('The survey team mapped the coast by refusing to record its shape, landmarks, or position.','The survey team mapped the coast by recording its shape and landmarks on a chart.','不记录地形就没有绘制或测绘地图。'),[Q('A road map primarily shows?','the locations of roads and places','how loud a speaker sounds','a person’s marital status','地图用图示呈现地点和道路。'),Q('A brain map is?','a diagram of how parts of a system are arranged','a paper route to a seaside town','a list of wedding guests','map 的图谱义表示系统组成部分的布局。'),Q('In “surveyors mapped the coast,” map means?','made a chart of the area','married two people','marked a calendar month','map 可作动词表示测绘。'),Q('To map out a relocation is to?','plan its stages carefully','draw a coastline by hand only','remove every note from a page','map out 比喻逐步安排计划。')]);
P('maple','Maple is the common name for trees of the genus Acer and for the pale, often hard wood obtained from them.',C('maple.s1','树木辨认','In autumn, the maple beside the school turned red, while its broad leaves fell across the path.','秋天，学校旁的枫树变红，宽大的叶子落满小路。','In autumn / the maple beside the school turned red / while its broad leaves / fell across the path.','maple 作可数名词，指枫树；maple leaves 是自然搭配。','树种和秋季变色的叶子都符合 s1。'),M('The carpenter labelled the pale maple tabletop as oak, although its grain and source were clearly identified as maple.','The carpenter labelled the pale tabletop as maple after confirming the wood species.','把已确认的 maple 木材称作另一树种会造成错误识别。'),[Q('Maple is the name of a?','tree in the genus Acer','type of ocean fish','musical hand rattle','maple 指槭树属的树木。'),Q('What happened to the school’s maple in autumn?','its leaves turned red and fell','it produced a loudspeaker','it was mapped as a coastline','秋天枫叶变红并落下。'),Q('Maple can also refer to?','the tree’s hardwood','a formal midday meal','a type of vegetable fat','maple 也可指枫木。'),Q('Which phrase is natural?','maple leaves','maple of leaveses','maplely leaf','maple leaves 是正确名词搭配。','grammar')]);
P('mar','Mar comes from Old English merran (“spoil, hinder”) and means to damage the appearance, enjoyment, reputation, or relationship of something.',[C('mar.s1','活动受扰','A sudden power cut marred the concert, interrupting the final song and leaving the hall in darkness.','突然停电破坏了音乐会的气氛，打断最后一首歌，还让大厅陷入黑暗。','A sudden power cut marred the concert / interrupting the final song / and leaving the hall / in darkness.','mar 作及物动词，宾语 concert 表示破坏活动的体验或效果。','停电影响演出和观众体验，符合 s1。'),C('mar.s2','声誉受损','The bribery scandal marred the mayor’s reputation despite his earlier work on public housing.','尽管市长此前推进了公共住房工作，贿赂丑闻仍损害了他的声誉。','The bribery scandal marred / the mayor’s reputation / despite his earlier work / on public housing.','mar 可用于抽象对象 reputation，表示使其变坏或受损。','丑闻使公众对市长评价变差，符合 s2。')],M('The power cut marred the concert by making the music clearer and improving the audience’s experience.','The power cut marred the concert by interrupting the performance and spoiling the experience.','改善体验与“破坏”意思相反。'),[Q('What marred the concert?','a sudden power cut','a maple tree outside','a printed manuscript','停电打断音乐会并使大厅停电。'),Q('To mar a reputation is to?','damage it','make it perfectly clear','map it onto a chart','mar 可表示损害名誉。'),Q('Which sentence uses mar naturally?','The stain marred the white tablecloth.','The stain marred the tablecloth by cleaning it.','The tablecloth marred the stain into a map.','污渍会破坏桌布外观。'),Q('Mar is closest to?','spoil','masticate','march','spoil 可表示损害或弄糟。')]);
P('maraca','Maraca came into English from Spanish or Portuguese maraca, from a Tupi name for a hand-held rattle used in music.',C('maraca.s1','乐器排练','The percussionist shook a maraca beside the drum to add a crisp rattling rhythm to the song.','打击乐手在鼓旁摇动一只沙球，为歌曲加入清脆的沙响节奏。','The percussionist shook / a maraca beside the drum / to add / a crisp rattling rhythm.','maraca 作可数名词；shake a maraca 描述这种手持乐器的演奏动作。','手摇发声的打击乐器符合 s1。'),M('The musician called the maraca a string instrument and played it by plucking its strings.','The musician called the maraca a percussion instrument and shook it to make a rattling sound.','沙球靠摇动发声，不是靠拨弦演奏。'),[Q('A maraca is a?','hand-held percussion rattle','large stone used for sculpture','map of a music hall','maraca 是手持摇奏打击乐器。'),Q('How did the percussionist play it?','by shaking it','by plucking its strings','by blowing through a mouthpiece','沙球摇动后发出沙响。'),Q('What sound did it add?','a crisp rattling rhythm','a long silent pause','a loud engine noise','maraca 为歌曲加入清脆的节奏。'),Q('Which language supplied the word maraca to English?','Spanish or Portuguese','Old Norse only','Japanese','英语 maraca 经由西班牙语或葡萄牙语借入。')]);
P('marathon','Marathon takes its name from Marathon in Greece and names a 42.195-kilometre race; figuratively it describes a long, demanding event.',[C('marathon.s1','城市赛事','Thousands of runners entered the city marathon, which followed a measured 42.195-kilometre course.','数千名跑者参加了城市马拉松，赛道全长为测定的42.195公里。','Thousands of runners entered / the city marathon / which followed / a measured 42.195-kilometre course.','marathon 作可数名词，体育义距离为42.195公里。','明确赛道长度符合正式马拉松赛 s1。'),C('marathon.s2','长时间活动','After a six-hour planning marathon, the committee finally agreed on a practical route for the festival.','经过六小时的马拉松式规划会议，委员会终于为节日确定了一条可行路线。','After a six-hour planning marathon / the committee finally agreed / on a practical route / for the festival.','marathon 可比喻持续时间极长、令人疲惫的活动。','长达六小时的会议符合持久艰苦活动义 s2。'),C('marathon.s3','长时间形容','The team faced a marathon editing session to finish the manuscript before the deadline.','团队面临一场漫长的编辑工作，必须在截止时间前完成稿件。','The team faced / a marathon editing session / to finish the manuscript / before the deadline.','marathon 作前置修饰语，形容耗时且需要耐力的活动。','编辑工作耗时漫长，符合形容词性用法 s3。')],M('The race was a marathon even though it covered only one hundred metres and ended in a few seconds.','The race was a marathon because its course measured 42.195 kilometres.','百米短跑不属于马拉松赛。'),[Q('A standard marathon race is?','42.195 kilometres long','one hundred metres long','a month-long writing contest','马拉松正式距离是42.195公里。'),Q('A planning marathon is?','a very long, demanding meeting','a short conversation lasting seconds','a race through a map','比喻义指持续很久、令人疲惫的活动。'),Q('Why was the editing session called a marathon?','it lasted a long time and required endurance','it was held beside a maple tree','the editor ran exactly 42 kilometres','长时间、高强度的编辑工作可比喻为 marathon。'),Q('Marathon is named after a place in?','Greece','Canada','Japan','马拉松名称来自希腊的 Marathon。')]);
P('marble','Marble came through Old French and Latin from Greek marmaros; it means a hard building stone, a small glass playing ball, or informally one’s sanity.',[C('marble.s1','雕塑材料','The sculptor chose white marble because its fine grain could hold the delicate folds of the statue’s robe.','雕塑家选择白色大理石，因为细密纹理能够呈现雕像长袍的精致褶皱。','The sculptor chose white marble / because its fine grain / could hold / the delicate folds of the statue’s robe.','marble 作不可数材料名词，指大理石。','石材用于雕像雕刻，符合 s1。'),C('marble.s2','儿童游戏','The children traded blue glass marbles during recess and kept them in a small cloth bag.','课间时，孩子们交换蓝色玻璃弹珠，并把它们装在一个小布袋里。','The children traded / blue glass marbles / during recess / and kept them in a small cloth bag.','marble 作可数名词，指儿童游戏用的小玻璃球。','可交换的小玻璃球符合 s2。'),C('marble.s3','习语用法','After three nights without sleep, Luis joked that he was losing his marbles and needed a proper rest.','连续三晚没睡后，路易斯开玩笑说自己快失去理智了，需要好好休息。','After three nights without sleep / Luis joked / that he was losing his marbles / and needed a proper rest.','lose one’s marbles 是非正式习语，意为失去理智，不涉及真实弹珠。','疲劳让他说自己快失去理智，符合 s3。')],M('The sculptor carved the statue from marble, a soft fabric woven from cotton thread.','The sculptor carved the statue from marble, a hard stone suitable for sculpture.','大理石是硬质石材，不是棉布。'),[Q('Marble used by a sculptor is?','a hard stone','a soft dairy spread','a hand-held rattle','建筑或雕塑义的 marble 是硬石材。'),Q('Children’s marbles are?','small balls used in a game','pages of an unpublished book','pieces of seaweed','游戏义指小玻璃弹珠。'),Q('“Lose your marbles” means?','lose your sanity, informally','misplace a stone sculpture only','run a marathon','习语 lose one’s marbles 表示失去理智。'),Q('Which material best suits a carved statue?','marble stone','a glass toy marble','a written margin','雕像可以由大理石雕刻。')]);
P('March','March comes from Latin Martius, named for Mars; it is the third month of the year, and each occurrence is one March.',[C('March.s1','日历安排','The conference will begin in March, after the winter term ends and before the spring break.','会议将在三月举行，时间是冬季学期结束后、春假之前。','The conference will begin / in March / after the winter term ends / and before the spring break.','月份名称 March 首字母大写，常与 in 连用。','会议安排在二月之后、四月之前的月份。'),C('March.s2','年度记事','March was unusually wet that year, although the following March brought almost no rain.','那一年的三月异常潮湿，但次年三月几乎没有下雨。','March was unusually wet that year / although the following March / brought almost no rain.','每年 occurrence of March 都可指该月份的一次具体经历。','句中比较相邻年份的两个三月。')],M('The invitation says the meeting is in march, treating the month name as an ordinary lowercase noun.','The invitation says the meeting is in March, with the month name capitalized.','英语月份名称须大写首字母。','capitalization'),[Q('March is which month of the year?','the third','the first','the twelfth','March 是一年中的第三个月。'),Q('How is an English month name written?','with an initial capital letter','always in all lowercase letters','with a hyphen after the first letter','月份名称首字母大写。'),Q('“The following March” refers to?','the month of March in the next year or sequence','the previous February only','a type of manuscript','following March 指后一个年份或顺序中的三月。'),Q('March is named after which Roman god?','Mars','Maple','Marlin','March 源自以罗马战神马尔斯命名的 Martius。')]);
P('margarine','Margarine was coined in French from Greek margaron (“pearl”), referring to the pearly appearance of the original butter substitute.',C('margarine.s1','食品标签','The recipe uses margarine instead of butter, making the cake suitable for a guest who avoids dairy products.','这个配方用人造奶油代替黄油，使蛋糕适合不吃乳制品的客人。','The recipe uses margarine / instead of butter / making the cake suitable / for a guest who avoids dairy products.','margarine 作不可数食物名词，常与 butter 对比。','植物脂肪制品被用来替代黄油，符合 s1。'),M('The baker used margarine as a dairy-free substitute even though the ingredient was ordinary butter made from milk.','The baker used vegetable-fat margarine as a substitute for dairy butter.','普通乳脂黄油不是人造奶油。'),[Q('Margarine is commonly used as a substitute for?','butter','maple wood','marble stone','人造奶油常用于替代黄油。'),Q('What is margarine mainly made from?','vegetable fat','marble dust','maple leaves','词条定义主要成分为植物脂肪。'),Q('Why did the recipe use margarine?','to accommodate a guest avoiding dairy','to make a manuscript readable','to map a coastline','它替代乳制黄油以适应客人的饮食选择。'),Q('Which pair is natural?','margarine instead of butter','margarine beside a marble statue','many margarine','margarine 和 butter 常作为替代品对照。','collocation')]);
P('margin','Margin comes from Latin margo (“edge”); it means page-edge space, a difference or profit, or extra time, space, or safety allowed.',[C('margin.s1','书稿校对','Please leave a wide margin beside the manuscript so the editor can write comments without covering the text.','请在稿件旁留出宽页边，方便编辑写批注而不遮住正文。','Please leave / a wide margin beside the manuscript / so the editor can write comments / without covering the text.','margin 作可数名词，指页面边缘的空白；leave a margin 是自然搭配。','预留给批注的页面空白符合 s1。'),C('margin.s2','选举结果','The candidate won by a narrow margin after the final count added only a few votes to her total.','最后计票只给她增加了几票，因此这位候选人以微弱优势获胜。','The candidate won / by a narrow margin / after the final count / added only a few votes.','margin 可指两个数值的差额或获胜优势。','胜出只差少数票，符合 s2。'),C('margin.s3','零售利润','The shop raised its prices slightly to protect its profit margin after shipping costs increased.','运输成本上涨后，商店略微提高价格以保护利润空间。','The shop raised its prices slightly / to protect its profit margin / after shipping costs increased.','profit margin 指销售收入与成本之间的利润差额。','价格调整是为了维持利润。'),C('margin.s4','安全余量','The pilot kept a safety margin of extra fuel in case strong winds lengthened the route.','飞行员额外保留了燃油安全余量，以防强风延长航程。','The pilot kept / a safety margin of extra fuel / in case strong winds / lengthened the route.','margin 可指额外预留的时间、空间或安全余量。','备用燃油为风险留出缓冲，符合 s4。')],M('The pilot kept no safety margin at all, yet described the empty reserve as extra fuel for emergencies.','The pilot kept a safety margin by carrying extra fuel for unexpected delays.','没有任何备用燃油就没有安全余量。'),[Q('A page margin is?','blank space at the edge of a page','a small glass ball','a third month of the year','页面 margin 指纸面边缘留白。'),Q('Winning by a narrow margin means?','winning by only a small difference','winning by an overwhelming number','not winning at all','narrow margin 表示优势很小。'),Q('A profit margin concerns?','the difference between revenue and costs','the blank edge of a manuscript only','a fish’s length','profit margin 指利润差额。'),Q('A safety margin of fuel is?','extra fuel kept as a reserve','fuel removed before the trip','a printed note beside a map','安全余量是为意外预留的额外燃油。')]);
P('marginal','Marginal comes from margin and ultimately Latin margo (“edge”); it means at an edge or, figuratively, too small to matter much.',[C('marginal.s1','边缘地带','The village lies in a marginal area of the wetland, where dry ground meets seasonal marsh.','村庄位于湿地的边缘地带，那里干燥地面与季节性沼泽相接。','The village lies / in a marginal area of the wetland / where dry ground / meets seasonal marsh.','marginal 作形容词修饰 area，表示位于边缘。','村庄处在两种地貌相接的外围地区，符合 s1。'),C('marginal.s2','成绩变化','The student’s marginal improvement did not change her overall grade, which remained just below the pass mark.','这名学生的进步微乎其微，没有改变总成绩；她仍略低于及格线。','The student’s marginal improvement / did not change her overall grade / which remained / just below the pass mark.','marginal 可表示程度很小、影响有限。','微小进步不足以改变成绩，符合 s2。')],M('The report called the improvement marginal even though the score jumped from 40 to 98 and transformed the outcome.','The report called the improvement substantial because the score rose from 40 to 98.','如此显著的分数增长不属于 marginal 的“微小”义。'),[Q('A marginal area is located?','at or near an edge','in the exact centre','under the sea floor','marginal 的字面义是边缘的。'),Q('A marginal improvement is?','very small and limited','large enough to transform everything','a guaranteed failure','marginal 可表示微小、不重要的。'),Q('What remained below the pass mark?','the student’s overall grade','the edge of the wetland','a map’s printed margin','微小进步后总成绩仍未及格。'),Q('Marginal is related to which noun?','margin','maraca','marriage','marginal 由 margin 加 -al 构成。','word-formation')]);
P('marginally','Marginally is formed from marginal plus -ly and means by a very small amount or only just at an acceptable edge.',[C('marginally.s1','数据比较','The revised battery lasted marginally longer than the old model, adding only three minutes in the test.','改版电池在测试中只比旧型号多用了三分钟，续航时间略长。','The revised battery lasted / marginally longer / than the old model / adding only three minutes.','marginally 修饰比较级 longer，表示差距很小。','只多三分钟说明增加幅度有限，符合 s1。'),C('marginally.s2','勉强过关','After the final repair, the machine was marginally safe to operate, though engineers still recommended replacing it soon.','最后一次维修后，这台机器勉强达到可运行的安全边缘，不过工程师仍建议尽快更换。','After the final repair / the machine was marginally safe / to operate / though engineers still recommended replacing it.','marginally safe 表示勉强够到可接受标准，而非充分安全。','仍建议更换说明仅勉强达标，符合 s2。')],M('The revised battery lasted marginally longer, adding twelve extra hours to a ten-minute test.','The revised battery lasted marginally longer, adding only three minutes to the test.','相对于测试时长多出十二小时并非微小差额。'),[Q('“Marginally longer” means?','longer by a very small amount','twice as long','shorter by a large amount','marginally 修饰比较级，表示只多一点。'),Q('“Marginally safe” suggests the machine is?','only just at an acceptable safety edge','completely free of every risk','certain to fail immediately','marginally 可表示勉强达到某个标准。'),Q('How much extra battery time was recorded?','three minutes','twelve hours','one full month','测试只多出三分钟。'),Q('Which phrase uses marginally naturally?','marginally better than before','marginally the bestest','a marginally margin','marginally 常修饰比较级。','grammar')]);
P('marine','Marine comes from Latin marinus, from mare (“sea”); it can describe sea-related things, a Marine soldier, or ships considered as a group.',[C('marine.s1','海洋生态','Marine algae covered the rocks below the tide line and provided food for small invertebrates.','潮线以下的岩石上长满海藻，为小型无脊椎动物提供食物。','Marine algae covered the rocks / below the tide line / and provided food / for small invertebrates.','marine 作形容词修饰 algae，表示与海洋有关或海生的。','潮线下的海藻属于海洋生态。'),C('marine.s2','军事任务','The marine checked his radio before joining the unit assigned to protect the coastal landing site.','这名海军陆战队士兵在加入负责保护沿岸登陆点的部队前检查了无线电。','The marine checked his radio / before joining the unit / assigned to protect / the coastal landing site.','Marine 作可数名词可指海军陆战队士兵，军种名常大写。','执行沿岸登陆任务的士兵符合 s2。'),C('marine.s3','航运公司','The company expanded its marine after purchasing three cargo vessels for overseas routes.','公司购入三艘用于海外航线的货船后扩大了船队。','The company expanded its marine / after purchasing three cargo vessels / for overseas routes.','marine 作名词可集合指船舶或海运业务，使用需结合航运语境。','扩大船只组合与海运业务符合 s3。')],M('Marine algae were growing in the dry desert far from salt water, yet scientists called them sea organisms.','Marine algae grew below the tide line in seawater.','远离海水的沙漠环境不符合海生藻类的语境。'),[Q('Marine algae are?','organisms connected with the sea','soldiers carrying out a march','wood used for a sculpture','marine 可作形容词表示海洋的、海生的。'),Q('A Marine in the military sense is?','a soldier trained for sea and land service','a sailor’s map','a type of fish','Marine 作名词指海军陆战队士兵。'),Q('What did the company buy to expand its marine?','cargo vessels','maple trees','maraca instruments','该句把 marine 用作船舶或海运业务集合名词。'),Q('Marine ultimately comes from a Latin word for?','sea','margin','marriage','mare 的意思是“海”。')]);
P('marital','Marital comes from Latin maritalis, related to maritus (“husband”), and means relating to marriage or to the relationship between spouses.',[C('marital.s1','法律文件','The form asks for marital status so the agency can record whether each applicant is single, married, or divorced.','表格询问婚姻状况，以便机构记录申请人是单身、已婚还是离异。','The form asks for marital status / so the agency can record / whether each applicant is single, married, or divorced.','marital status 是固定搭配，表示婚姻法律状态。','表格登记个人婚姻状况，符合 s1。'),C('marital.s2','夫妻咨询','The counsellor helped them discuss marital disagreements without blaming each other.','咨询师帮助他们讨论夫妻间的分歧，而不互相指责。','The counsellor helped them discuss / marital disagreements / without blaming each other.','marital 可形容夫妻双方之间的关系或问题。','争执发生在配偶之间，符合 s2。')],M('The form asked for marital status to record each applicant’s favourite musical instrument.','The form asked for marital status to record whether each applicant was single, married, or divorced.','婚姻状况不用于登记音乐偏好。'),[Q('Marital status refers to?','whether someone is single, married, or divorced','whether someone owns a map','whether someone has a marine radio','marital status 指婚姻状态。'),Q('Marital disagreements occur?','between spouses','between two unrelated maps','only between ships at sea','marital 可表示夫妻之间的。'),Q('Which phrase is standard?','marital status','marital instrument','marital of the office','marital status 是自然固定搭配。','collocation'),Q('Marital is related to which noun?','marriage','maraca','maple','marital 表示与婚姻有关。')]);
P('maritime','Maritime comes from Latin maritimus, from mare (“sea”); it relates to ships, sea trade, or areas and people near the sea.',[C('maritime.s1','港口法规','The country updated its maritime rules to clarify how cargo ships must report pollution at sea.','该国更新了海事规则，明确货船必须如何报告海上污染。','The country updated / its maritime rules / to clarify / how cargo ships must report pollution at sea.','maritime 作形容词修饰 rules，指海事、航运或海上贸易相关。','规则约束货船在海上的行为，符合 s1。'),C('maritime.s2','沿海气候','The town has a maritime climate, with mild winters and frequent rain brought in from the ocean.','这座城镇属于海洋性气候，冬季温和，经常有海上带来的降雨。','The town has / a maritime climate / with mild winters / and frequent rain brought in from the ocean.','maritime 也可描述沿海地区或受海洋影响的气候。','临海带来温和潮湿气候，符合 s2。')],M('The shipping authority called its maritime rules inland farming laws that never applied to vessels or the sea.','The shipping authority called its maritime rules regulations governing ships and activity at sea.','与船舶和海洋无关的农法不属于 maritime rules。'),[Q('Maritime rules govern?','ships and activities at sea','marble sculptures only','marital status forms','maritime 指海事或海运相关。'),Q('A maritime climate is influenced by?','the nearby ocean','the desert far inland','a loudspeaker in a city','沿海气候受海洋影响。'),Q('Which phrase is natural?','maritime trade','maritime marriage status','maritimately ship','maritime trade 是海上贸易。'),Q('Maritime derives from a Latin word meaning?','sea','many','handwritten','mare 的意思是“海”。')]);
P('mark','Mark comes from Old English mearc (“boundary, sign”); it can mean a stain, a grade, a symbol, to label, to grade, or to commemorate.',[C('mark.s1','表面污迹','A dark mark on the white tablecloth remained after the coffee was wiped away.','咖啡擦掉后，白色桌布上仍留着一块深色污迹。','A dark mark / on the white tablecloth / remained / after the coffee was wiped away.','mark 作可数名词，指表面颜色不同的痕迹。','擦拭后仍有异色区域，符合 s1。'),C('mark.s2','考试成绩','The teacher returned each paper with a mark and a short note explaining the result.','老师把试卷发还给学生，每张都写有分数和简短评语。','The teacher returned each paper / with a mark / and a short note / explaining the result.','mark 作名词可指考试分数或等级。','试卷上记录的成绩符合 s2。'),C('mark.s3','符号提示','A red mark beside the paragraph showed the proofreader where a correction was needed.','段落旁的红色记号标出了校对员需要修改的位置。','A red mark / beside the paragraph / showed the proofreader / where a correction was needed.','mark 可指写下的符号或标记。','红色符号指示修改位置，符合 s3。'),C('mark.s4','地图标注','Please mark the emergency exit on the map before the safety briefing begins.','安全简报开始前，请在地图上标出紧急出口。','Please mark / the emergency exit / on the map / before the safety briefing begins.','mark 作及物动词，mark something on a map 表示标注位置。','把出口位置标在地图上，符合 s4。')],M('The teacher marked the essay by refusing to assign any score, comment, or indication of the student’s performance.','The teacher marked the essay by assigning a grade and adding comments.','mark 在批改义中需要给出分数或评语。'),[Q('A dark mark on cloth is?','a visible stain or patch','a high exam score','a whole month','mark 可指表面留下的污迹。'),Q('A teacher’s mark is?','a score or grade','a sea route','a maple tree','mark 可指考试成绩。'),Q('What did the red mark beside the paragraph show?','where a correction was needed','the paper’s weight','the author’s marital status','记号标出需要修改的地方。'),Q('To mark an exit on a map is to?','put a sign showing its location','erase the whole map','score an exam','mark 可作动词表示标示位置。')]);
P('marked','Marked is the past participle of mark and an adjective meaning clearly noticeable or significant.',C('marked.s1','实验结果','The treatment produced a marked improvement in the patient’s mobility within two weeks.','两周内，这项治疗使患者的行动能力有了明显改善。','The treatment produced / a marked improvement / in the patient’s mobility / within two weeks.','marked 作形容词修饰 improvement，表示明显、显著。','短期内出现清楚可见的改善，符合 s1。'),M('The report described a marked improvement even though measurements before and after treatment were identical.','The report described a marked improvement because the patient’s mobility increased clearly after treatment.','前后测量完全相同，不能称为明显改善。'),[Q('A marked improvement is?','clearly noticeable','too small to detect','a stain on a map','marked 表示显著、明显的。'),Q('What improved after treatment?','the patient’s mobility','the map’s coastline','the room’s loudness','语境说明患者行动能力明显改善。'),Q('Which phrase is natural?','a marked difference','a markedly difference','marking difference','marked 可作形容词修饰 difference。','grammar'),Q('Marked is historically related to which verb?','mark','map','marry','marked 是 mark 的过去式/分词形式。')]);
P('markedly','Markedly is formed from marked plus -ly and means noticeably or to a significant extent.',C('markedly.s1','统计变化','After the new timetable began, delays fell markedly compared with the previous month.','新时刻表实施后，与上个月相比，延误次数明显下降。','After the new timetable began / delays fell markedly / compared with / the previous month.','markedly 作副词修饰 fell，表示变化幅度显著。','延误明显减少，符合 s1。'),M('Delays fell markedly even though the count changed from 10 to 10 and no difference could be observed.','Delays fell markedly when the count dropped from 40 to 10 in the same period.','数据没有变化时不能说显著下降。'),[Q('If delays fell markedly, they?','decreased noticeably','stayed exactly the same','increased by an invisible amount','markedly 表示变化明显。'),Q('What was compared?','delays after and before the new timetable','two types of maple wood','two marital forms','延误次数与前一个月作比较。'),Q('Markedly is an adverb that modifies?','fell','timetable','month','markedly 修饰动词 fell。','grammar'),Q('Which phrase is correct?','markedly different','markedly difference','a markedly of delays','markedly 可修饰形容词 different。','grammar')]);
P('marker','Marker is formed from mark plus -er and means a person or thing that marks, including a pen used to write visible marks.',C('marker.s1','地图标注','The guide used a red marker to circle the trailhead on the paper map.','导游用红色记号笔在纸质地图上圈出小径起点。','The guide used / a red marker / to circle the trailhead / on the paper map.','marker 作可数名词，指用于标记的笔或其他工具。','记号笔在地图上留下可见标记，符合 s1。'),M('The guide used a marker to erase the map without leaving any mark or line.','The guide used a marker to draw a visible circle around the trailhead.','记号笔用于留下标记，不是擦除标记。'),[Q('A marker in the guide’s hand is?','a pen used to make visible marks','a formal wedding document','a wetland plant','marker 可指记号笔。'),Q('What did the guide circle?','the trailhead on the map','a wedding cake','a page of marble','记号笔圈出了小径起点。'),Q('A person who marks a route could also be called a?','marker','margarine','marlin','marker 也可指做标记者。'),Q('Which phrase is natural?','a red marker pen','a marker to masticate a meal','markerly red','marker pen 是自然搭配。','collocation')]);
P('market','Market comes through Old French from Latin mercatus (“trading”); it is a place or activity of buying and selling, and a verb meaning to promote goods.',[C('market.s1','农贸集市','Local growers set up stalls at the Saturday market to sell apples, cheese, and fresh bread.','当地种植者在周六集市摆摊，出售苹果、奶酪和新鲜面包。','Local growers set up stalls / at the Saturday market / to sell apples, cheese, / and fresh bread.','market 作可数名词可指商品买卖的实际场所。','摊位上售卖食品，符合集市义 s1。'),C('market.s2','产品需求','The market for home batteries grew after electricity prices rose and more households installed solar panels.','电价上涨、更多家庭安装太阳能板后，家用电池的市场需求扩大了。','The market for home batteries grew / after electricity prices rose / and more households / installed solar panels.','market 可指某商品的买卖活动、需求或行情。','消费者需求增加带动该产品市场扩大。'),C('market.s3','产品推广','The company markets its software to small clinics by demonstrating how it saves reception staff time.','该公司通过展示软件如何节省前台员工时间，向小型诊所推销产品。','The company markets its software / to small clinics / by demonstrating / how it saves reception staff time.','market 作及物动词，market a product to a group 表示向其营销。','演示价值以推广软件，符合动词义 s3。')],M('The company marketed its software by hiding it from clinics and refusing to tell potential users about it.','The company marketed its software to clinics by explaining its benefits to potential users.','隐瞒产品且不接触潜在用户不是营销推广。'),[Q('At a Saturday market, growers usually?','sell goods at stalls','write marriage certificates','repair ships at sea','market 可指买卖商品的场所。'),Q('A market for home batteries means?','demand and trading for that product','a single battery’s physical map','a wedding celebration','market 可指产品相关的需求和交易活动。'),Q('To market software to clinics is to?','promote and sell it to them','hide it from them','use it as a medical tool','market 作动词表示营销产品。'),Q('Which phrase is natural?','a market for electric cars','a market of marrying someone','market the map into a wetland','market for a product 表示该产品的市场。','collocation')]);
P('marketable','Marketable is formed from market plus -able and describes goods or skills that people are likely to want to buy or employ.',C('marketable.s1','职业技能','The course helps graduates build marketable skills in data analysis and clear technical writing.','这门课程帮助毕业生培养数据分析和清晰技术写作等有市场需求的技能。','The course helps graduates build / marketable skills / in data analysis / and clear technical writing.','marketable 作形容词修饰 skills，表示雇主或市场需要的。','技能能满足岗位需求，符合 s1。'),M('The brochure called the product marketable even though no customer wanted it and every shop refused to stock it.','The brochure called the product marketable because customers showed demand and shops agreed to sell it.','没有消费者需求且商店拒售，不支持适销评价。'),[Q('Marketable skills are skills that?','employers or customers are likely to want','cannot be used in any job','are only visible on a map','marketable 表示有市场需求。'),Q('Why were the graduates’ skills marketable?','they matched needs in data analysis and writing','they had no practical use','they were too costly to teach','课程教授市场需要的技能。'),Q('Which item is most likely marketable?','a product customers actively seek','an unwanted item every shop rejects','a private document with no buyer','有消费者需求的商品更适销。'),Q('The suffix -able often means?','able or suitable to be acted on','the state of being married','a person who marks','-able 在 marketable 中表示适合进入市场销售。','word-formation')]);
P('marketing','Marketing comes from market plus -ing and means the work of promoting and selling products, or more broadly the activity of trade.',[C('marketing.s1','产品推广','The marketing team tested two adverts to learn which message persuaded more shoppers to try the new cereal.','营销团队测试了两则广告，以了解哪种信息更能说服购物者尝试新麦片。','The marketing team tested two adverts / to learn / which message persuaded more shoppers / to try the new cereal.','marketing 作不可数名词，指推广产品并促进销售的工作。','广告测试用于推广新品，符合 s1。'),C('marketing.s2','市场交易','The report examined the marketing of farm produce, from growers’ stalls to wholesale buyers.','报告考察了农产品的市场交易过程，从种植者的摊位到批发买家。','The report examined / the marketing of farm produce / from growers’ stalls / to wholesale buyers.','marketing 也可表示商品在市场中买卖或流通过程。','报告追踪农产品从生产者到批发商的交易过程。')],M('The marketing campaign increased sales by making sure that no one learned the product existed.','The marketing campaign increased sales by informing likely customers about the product and its benefits.','不让消费者知道产品存在无法促进销售。'),[Q('A marketing team mainly works to?','promote and sell products','repair a coastal marsh','perform a wedding ceremony','marketing 指产品推广与销售活动。'),Q('Which action is a marketing test?','comparing two adverts with shoppers','weighing luggage at an airport','marking a manuscript for grammar','广告对比测试属于营销。'),Q('In “marketing of farm produce,” it can refer to?','the buying and selling of goods','only the design of a farm map','a marital ceremony','marketing 可指商品进入市场交易的过程。'),Q('Marketing is related to which word?','market','martyr','marble','marketing 源自 market。')]);
P('marketplace','Marketplace combines market and place and means a physical or online place where goods are offered for sale.',C('marketplace.s1','线上购物','The small publisher found a global marketplace online where readers could order books in several languages.','这家小型出版社在网上找到了一个全球市场，读者可以订购多种语言的书籍。','The small publisher found / a global marketplace online / where readers could order books / in several languages.','marketplace 作可数名词，可指实体集市或网络交易平台。','在线平台供买卖书籍，符合 s1。'),M('The website was a marketplace although it displayed no goods, accepted no orders, and enabled no buying or selling.','The website was a marketplace because sellers listed goods there and customers could order them.','不展示商品且不能交易的平台不构成市场。'),[Q('An online marketplace allows people to?','list and buy or sell goods','measure the luminosity of stars','record a marriage without a registrar','marketplace 是供商品交易的平台。'),Q('What could readers order in the example?','books in several languages','marble statues only','maraca instruments for a concert','平台上的读者能订购多语种书籍。'),Q('Which words form marketplace?','market + place','many + sided','mar + row','marketplace 是 market 与 place 的复合词。','word-formation'),Q('A physical marketplace might include?','stalls where sellers offer goods','a blank margin with no products','a private office with no trading','集市摊位是实体交易场所。')]);
P('markup','Markup combines mark and up; it can mean the amount added to a cost to set a selling price or a notation system used to annotate text.',[C('markup.s1','零售定价','The shop added a small markup to the wholesale cost to cover rent and staff wages.','商店在批发成本上加了一小笔价差，以支付租金和员工工资。','The shop added / a small markup / to the wholesale cost / to cover rent and staff wages.','markup 作可数名词，表示成本价上增加的金额或比例。','加价用来覆盖经营费用，符合 s1。'),C('markup.s1','文稿标注','The editor sent the markup back with tags showing where headings and quotations should appear.','编辑把带有标记的稿件发了回来，标签显示标题和引文应放在哪里。','The editor sent the markup back / with tags / showing where headings and quotations / should appear.','markup 也可指用标记或标签注明文本结构的方法。','标签标出文稿结构，符合 s2。')],M('The shop’s markup reduced the selling price below its wholesale cost while still increasing its profit.','The shop’s markup added an amount to the wholesale cost when setting its selling price.','markup 通常是在成本上加价，不是降到成本以下。'),[Q('A retail markup is?','an amount added to the cost price','a discount below cost','a type of tent','markup 的商业义指在成本上加的价格。'),Q('Why did the shop add a markup?','to help cover rent and wages','to reduce its price below cost','to mark a map’s coastline','加价用于覆盖经营成本。'),Q('An editor’s markup may contain?','tags indicating headings and quotations','a list of groceries for sale','a ship’s anchor','markup 还可指稿件标注系统。'),Q('Which phrase is natural?','a 20 percent markup','a markup of marriage status','marking-up the table into a map','markup 可与百分比搭配表示加价幅度。','collocation')]);
P('marlin','Marlin is the common name of large billfish in the family Istiophoridae, prized in sport fishing.',C('marlin.s1','海洋生物','A marlin surfaced beside the research vessel, its long bill cutting through the water before it dived again.','一条枪鱼在科研船旁跃出水面，长吻划过水面后又潜了下去。','A marlin surfaced / beside the research vessel / its long bill cutting through the water / before it dived again.','marlin 作可数名词，指大型枪鱼；bill 描述其长而尖的吻部。','体型大、具有长吻的海鱼符合 s1。'),M('The guide identified the marlin as a small freshwater fish with no projecting bill.','The guide identified the marlin as a large ocean billfish with a long pointed bill.','枪鱼是大型海洋鱼类，不是无长吻的小型淡水鱼。'),[Q('A marlin is a large?','ocean billfish','marsupial mammal','piece of marble','marlin 指大型海洋枪鱼。'),Q('What feature did the marlin show above water?','its long bill','a pouch for its young','a handwritten manuscript','枪鱼有明显的长吻。'),Q('Where did it surface?','beside a research vessel','inside a marshland burrow','on a marketplace stall','例句中枪鱼在科研船旁跃出水面。'),Q('Marlin is especially associated with?','sport fishing','formal luncheons','map-making','枪鱼常见于运动钓鱼语境。')]);
P('maroon','The verb maroon is related to being stranded or isolated; its deeper history is complex, so no unsupported root is asserted.',C('maroon.s1','海岛救援','A rising tide marooned the hikers on a rocky islet until a rescue boat reached them at dawn.','涨潮把徒步者困在一座岩石小岛上，直到黎明时救援船赶到。','A rising tide marooned the hikers / on a rocky islet / until a rescue boat / reached them at dawn.','maroon 作及物动词，maroon someone somewhere 表示使其困在难以离开的地方。','潮水阻断离岛路线，导致人员受困。'),M('The storm marooned the hikers by giving them an open bridge and an easy route back to town.','The storm marooned the hikers on an island with no safe way to return to town.','有畅通桥梁和轻松返程路线就不构成受困。'),[Q('To maroon hikers on an islet is to?','leave them stranded there','guide them safely home','sell them a marketplace ticket','maroon 表示使人搁浅或孤立。'),Q('What prevented the hikers from leaving?','the rising tide','a quiet lullaby','a low markup','涨潮使他们暂时无法离开小岛。'),Q('Which sentence uses maroon as a verb?','The flood marooned the campers.','The marooned were a type of maple.','They bought maroon at the market.','maroon 作动词表示使人受困。'),Q('Which phrase is natural?','maroon someone on an island','maroon someone with a marriage','maroon a manuscript into a map','常用结构为 maroon someone somewhere。','collocation')]);
P('marque','Marque came from French marque (“brand, make”) and is chiefly used for the make or brand of a car.',C('marque.s1','汽车展览','The collector displayed a vintage marque whose emblem had appeared on racing cars for nearly a century.','收藏家展示了一个历史悠久的汽车品牌，其徽标近一个世纪来一直出现在赛车上。','The collector displayed / a vintage marque / whose emblem had appeared / on racing cars for nearly a century.','marque 作可数名词，主要用于汽车的品牌或制造商。','徽标和赛车联系到汽车品牌。'),M('The buyer asked for the car’s marque, meaning the exact month in which it was built.','The buyer asked for the car’s marque, meaning its make or brand.','marque 指品牌，不是生产月份。'),[Q('A car’s marque is its?','make or brand','marriage date','fuel level','marque 指汽车品牌。'),Q('What appeared on racing cars?','the marque’s emblem','a handwritten manuscript','a marshland plant','例句说品牌徽标出现在赛车上。'),Q('Which setting naturally uses marque?','a discussion of car manufacturers','a recipe for margarine','a lesson on lunar phases','marque 主要用于汽车品牌语境。'),Q('Marque was borrowed from which language?','French','Old English','Tupi','marque 来自法语 marque。')]);
P('marquee','Marquee came through French for a large tent or awning and now commonly means a large temporary tent used for outdoor events.',C('marquee.s1','户外婚礼','The wedding guests moved into the marquee when rain began, where long tables had been set beneath the canvas roof.','下雨后，婚礼宾客转移到大帐篷里；帆布顶下已经摆好了长桌。','The wedding guests moved / into the marquee / when rain began / where long tables had been set beneath the canvas roof.','marquee 作可数名词，指活动用的大型临时帐篷。','户外婚礼帐篷能容纳宾客并遮雨。'),M('The organisers called the tiny one-person umbrella a marquee for hundreds of dinner guests.','The organisers called the large event tent a marquee and seated the guests inside it.','只能容纳一人的小伞不是大型活动帐篷。'),[Q('A marquee at a wedding is?','a large event tent','a car brand','a fish with a long bill','marquee 指大型活动帐篷。'),Q('Why did guests move inside it?','rain began','the market closed','the editor marked the page','帐篷为宾客遮雨。'),Q('Where were the long tables?','beneath the canvas roof','on the Moon','inside a lung','长桌摆在帐篷帆布顶下。'),Q('Which phrase is natural?','a wedding marquee','a marquee of marital status','a marquely wedding','wedding marquee 是自然搭配。','collocation')]);
P('marriage','Marriage comes from marry plus -age and means the legal union of two people or the state of being married.',C('marriage.s1','法律登记','Their marriage was registered at the town office after both partners signed the civil certificate.','双方签署民事证书后，他们的婚姻在市政办公室登记。','Their marriage was registered / at the town office / after both partners / signed the civil certificate.','marriage 作可数名词，可指法律结合或婚姻关系。','双方依法登记，符合 s1。'),M('The official recorded a marriage even though neither person had consented or signed any legal document.','The official recorded the marriage after both partners gave consent and completed the legal registration.','没有双方同意或法律登记不能称为合法婚姻。'),[Q('Marriage is a?','legal union or state of being married','type of marine animal','small glass toy','marriage 指婚姻结合或婚姻状态。'),Q('Where was the marriage registered?','at the town office','at the Saturday food market','in a marshland','例句明确说在市政办公室登记。'),Q('What did both partners sign?','the civil certificate','a maraca','a maple leaf','双方签署了民事证书。'),Q('Marriage is formed from marry plus?','-age','-ly','-ish','marry 加 -age 构成 marriage。','word-formation')]);
P('married','Married is the past participle of marry and an adjective meaning joined in marriage or relating to marriage.',[C('married.s1','家庭情况','They have been married for twelve years and still celebrate the date they first met.','他们结婚十二年了，仍会庆祝初次相识的日子。','They have been married / for twelve years / and still celebrate / the date they first met.','be married 表示已婚状态；married 作表语形容词。','夫妻处于婚姻关系中，符合 s1。'),C('married.s1','配偶关系','The married couple made decisions together about where to live and how to care for their children.','这对已婚夫妇共同决定居住地点以及如何照顾孩子。','The married couple made decisions together / about where to live / and how to care for their children.','married 可作定语形容词修饰 couple。','couple 的关系与婚姻相关。')],M('She is married to Alex, but the form lists her as single and never joined in marriage.','She is married to Alex, and the form lists her marital status accurately.','已婚状态与单身登记相矛盾。'),[Q('Someone who is married is?','joined in marriage','looking for a market','a type of fish','married 表示已婚。'),Q('What do the married couple decide together?','where to live and how to care for children','how to map the coastline','which marque to race','句中说夫妻共同安排生活与育儿。'),Q('Which preposition commonly follows married?','to','at','with by','常说 be married to someone。','collocation'),Q('Married can be used as?','an adjective describing a person or couple','a noun for a page margin only','an adverb modifying loudly','married 常作形容词。')]);
P('marrow','Marrow comes from Old English mearg and means the soft tissue inside bones or, figuratively, the essential core of something.',[C('marrow.s1','医学说明','Bone marrow produces blood cells, so the doctor ordered tests after the patient’s counts remained unusually low.','骨髓会产生血细胞，因此患者的血细胞计数持续偏低后，医生安排了检查。','Bone marrow produces blood cells / so the doctor ordered tests / after the patient’s counts / remained unusually low.','marrow 作不可数医学名词，bone marrow 指骨内软组织。','血细胞生成与骨髓功能相关，符合 s1。'),C('marrow.s2','文本分析','The essay reaches the marrow of the debate by explaining the central disagreement rather than repeating side issues.','这篇文章通过阐明核心分歧而非重复枝节，触及了争论的要义。','The essay reaches / the marrow of the debate / by explaining the central disagreement / rather than repeating side issues.','to the marrow 可比喻某事的核心或精髓。','文章揭示争论的根本问题，符合 s2。')],M('The surgeon said bone marrow is the hard outer shell of a bone and contains no soft tissue.','The surgeon explained that bone marrow is soft tissue inside bones that helps produce blood cells.','骨髓位于骨内，质地柔软，并非外层硬壳。'),[Q('Bone marrow is?','soft tissue inside bones','the hard outside of a tree','a glass playing ball','marrow 指骨内的软组织。'),Q('What does bone marrow help produce?','blood cells','maraca rhythms','maritime rules','骨髓参与血细胞生成。'),Q('“The marrow of the debate” means?','its central or essential point','the empty margin of a page','the loudest part of a song','比喻义 marrow 指核心、要义。'),Q('Which phrase is natural?','bone marrow','marrow of a marriage certificate only','marrowly clear','bone marrow 是常见医学搭配。','collocation')]);
P('marry','Marry came through Old French marier from Latin maritare (“to wed”); it means to enter marriage, conduct a wedding, or combine things successfully.',[C('marry.s1','婚礼决定','They plan to marry next spring after completing their studies and arranging a small ceremony.','他们计划完成学业并安排一场小型仪式后，于明年春天结婚。','They plan to marry / next spring / after completing their studies / and arranging a small ceremony.','marry 作不及物动词时表示结婚；现代英语通常不说 marry with someone。','两人计划进入婚姻关系，符合 s1。'),C('marry.s2','主持仪式','The registrar will marry the couple in the garden if the weather remains dry.','如果天气持续干燥，登记官将在花园里为这对新人主持婚礼。','The registrar will marry the couple / in the garden / if the weather remains dry.','marry 作及物动词可表示主持婚礼或使两人成婚。','登记官执行婚礼仪式，符合 s2。'),C('marry.s3','设计融合','The chef married local herbs with a traditional sauce to create a lighter version of the dish.','厨师把当地香草与传统酱汁巧妙结合，做出这道菜的清淡版本。','The chef married local herbs / with a traditional sauce / to create / a lighter version of the dish.','比喻义 marry A with B 表示使不同事物和谐结合。','两种风味融合成一道菜，符合 s3。')],M('The couple married with each other at the registry office.','The couple married at the registry office.','marry 作“结婚”义时通常不接 with；可说 marry someone 或 marry someone to someone。','grammar'),[Q('They plan to marry next spring means they plan to?','enter a marriage together','sell a house at the market','mark a map','marry 可作不及物动词，表示结婚。'),Q('The registrar will marry the couple means the registrar will?','conduct their wedding ceremony','become their child','write a map for them','marry 可作及物动词，表示主持婚礼。'),Q('To marry herbs with a sauce is to?','combine them successfully','separate them permanently','sell them as a marriage certificate','比喻义表示把两种事物结合起来。'),Q('Which sentence is grammatical?','They decided to marry.','They decided to marry with each other.','They decided marrying each other with.','marry 表示结婚时可直接使用，不加 with。','grammar')]);
P('marsh','Marsh comes from Old English mersc and means low, soft, wet ground, often with grasses and shallow water.',[C('marsh.s1','湿地调查','Herons nested in the marsh where reeds and shallow pools provided cover and food.','苍鹭在沼泽中筑巢，芦苇和浅水池为它们提供了遮蔽与食物。','Herons nested / in the marsh / where reeds and shallow pools / provided cover and food.','marsh 作可数名词，指低洼潮湿的湿地。','芦苇和浅水池是沼泽地典型环境。'),C('marsh.s2','区域称呼','The northern marsh stretches for several kilometres between the village and the sea wall.','北部沼泽地带在村庄与海堤之间延伸数公里。','The northern marsh stretches / for several kilometres / between the village / and the sea wall.','a marsh 也可指一片具体的沼泽地带。','明确的地理片区符合 s2。')],M('The conservation team called the dry rocky hillside a marsh even though it had no wet ground, reeds, or shallow water.','The conservation team called the low, wet ground beside the pools a marsh.','干燥岩坡不符合沼泽的潮湿低地特征。'),[Q('A marsh is generally?','low, soft, wet ground','a dry mountain summit','a printed margin','marsh 指低洼潮湿的土地。'),Q('What nested in the marsh?','herons','marlin','marsupials only','句中说苍鹭在沼泽筑巢。'),Q('What did the northern marsh stretch between?','the village and sea wall','a marriage and a market','two manuscripts','例句定位了沼泽地带的边界。'),Q('Which plants are typical in the example?','reeds','maple boards','margarine','芦苇常见于浅水沼泽。')]);
P('marshal','Marshal came through Old French mareschal, originally a horse-servant or stable official; it names several officials and means to arrange people or things in order.',[C('marshal.s1','军事职衔','The field marshal reviewed the troops before the final parade through the capital.','阅兵队伍穿过首都前，陆军元帅检阅了部队。','The field marshal reviewed the troops / before the final parade / through the capital.','marshal 作名词可指某些军队中的高级军官。','field marshal 是高级军事职衔，符合 s1。'),C('marshal.s2','典礼安排','A parade marshal guided each school band to its place and kept the route clear for emergency vehicles.','游行司仪引导每支学校乐队就位，并为应急车辆保持路线畅通。','A parade marshal guided / each school band to its place / and kept the route clear / for emergency vehicles.','marshal 作名词可指组织队伍或活动秩序的官员。','典礼官负责引导队伍并维持路线。'),C('marshal.s3','整理证据','The lawyer marshalled the witness statements in chronological order before presenting them to the jury.','律师在向陪审团陈述前，按时间顺序整理了证人证词。','The lawyer marshalled / the witness statements / in chronological order / before presenting them to the jury.','marshal 作及物动词，表示有条理地整理、集结证据或人员。','按时间顺序组织证据符合 s3。')],M('The lawyer marshalled the evidence by scattering witness statements randomly and hiding the timeline.','The lawyer marshalled the evidence by arranging the statements in a clear chronological order.','打乱证据顺序并隐藏脉络不叫有条理地整理。'),[Q('A field marshal is?','a high-ranking military officer','a market seller','a wetland plant','field marshal 是高级军官职衔。'),Q('What did the parade marshal do?','guided bands and kept the route clear','graded every manuscript','sold tickets at a market','典礼官负责引导队伍和保持路线畅通。'),Q('To marshal witness statements is to?','organize them in a useful order','throw them away','translate them into a map','marshal 作动词表示有序整理证词。'),Q('Which sentence uses marshal as a verb?','She marshalled the facts before speaking.','The marshal is a type of fish.','They married a marsh.','marshal facts 表示整理事实。')]);
P('marshland','Marshland combines marsh and land and means an area of soft, wet ground, usually with grasses, reeds, or shallow water.',C('marshland.s1','自然保护','The reserve protects marshland where migrating birds feed during the spring and autumn seasons.','这处保护区维护着一片沼泽地，候鸟在春秋两季会在那里觅食。','The reserve protects marshland / where migrating birds feed / during the spring / and autumn seasons.','marshland 作不可数或集合名词，指沼泽湿地这一片区域。','候鸟在潮湿低地觅食，符合 s1。'),M('The map labelled the dry paved car park as marshland even though water and wetland plants were absent.','The map labelled the reed-covered wet ground beside the pools as marshland.','铺装干燥停车场不属于沼泽地。'),[Q('Marshland is an area of?','soft, wet ground','dry paved road','high stone mountain','marshland 指沼泽湿地。'),Q('Which animals fed there?','migrating birds','marble sculptures','market sellers','候鸟会在保护区湿地觅食。'),Q('Why does the reserve protect the marshland?','it provides habitat for birds','it is a place to sell margarine','it keeps manuscripts dry','湿地为候鸟提供栖息与食物。'),Q('Which two words form marshland?','marsh + land','marriage + land','market + marked','该复合词由 marsh 与 land 构成。','word-formation')]);
P('marshy','Marshy is formed from marsh plus -y and describes ground that is wet, soft, or likely to become waterlogged.',C('marshy.s1','徒步路线','The trail became marshy after several days of rain, so hikers used a wooden walkway to avoid sinking into the mud.','连日降雨后，小径变得泥泞潮湿，徒步者便走木栈道以免陷进泥里。','The trail became marshy / after several days of rain / so hikers used / a wooden walkway to avoid sinking.','marshy 作形容词修饰 trail，表示地面潮湿、松软。','雨后易陷入泥中的小径符合 s1。'),M('The ground was described as marshy even though it was dry, hard, and cracked underfoot.','The ground was described as marshy because rain left it soft and waterlogged.','干硬开裂的地面不符合 marshy。'),[Q('Marshy ground is?','wet and soft','dry and rocky','smooth marble','marshy 描述潮湿、松软的土地。'),Q('Why did hikers use the walkway?','to avoid sinking into the mud','to hear a maraca','to mark a wedding','木栈道避免陷进潮湿泥地。'),Q('What made the trail marshy?','several days of rain','a long dry season','a low markup','连日降雨让小径泥泞。'),Q('The suffix -y here means?','characterized by or full of marsh-like wetness','the past tense of marry','a person who marshals','-y 构成“有……特征的”形容词。','word-formation')]);
P('marsupial','Marsupial comes from Latin marsupium (“pouch”), from Greek marsypion; it names mammals whose young are carried in a pouch and can describe that feature.',[C('marsupial.s1','动物学观察','The kangaroo is a marsupial whose tiny newborn develops in its mother’s pouch after birth.','袋鼠是一种有袋类动物，幼崽出生后会在母亲的育儿袋中继续发育。','The kangaroo is a marsupial / whose tiny newborn develops / in its mother’s pouch / after birth.','marsupial 作可数名词，指有育儿袋的哺乳动物。','袋鼠幼崽在育儿袋中发育，符合 s1。'),C('marsupial.s2','动物特征','The marsupial pouch protects the young while they remain attached to the mother during early development.','有袋类动物的育儿袋在幼崽早期发育并依附母体时提供保护。','The marsupial pouch protects the young / while they remain attached to the mother / during early development.','marsupial 作定语可表示有袋类的或具有育儿袋的。','pouch 是这类动物的关键结构，符合 s2。')],M('A kangaroo is not a marsupial because its young develop only in an egg laid outside the mother’s body.','A kangaroo is a marsupial because its young continue developing in a pouch.','袋鼠不是产卵类动物；其幼崽在育儿袋中继续发育。'),[Q('A marsupial is a mammal whose young?','are carried in a pouch','hatch from hard eggs laid in trees','live only in seawater','有袋类幼崽由母体育儿袋携带。'),Q('Which animal is a marsupial?','a kangaroo','a marlin','a maple tree','袋鼠是典型有袋类动物。'),Q('What does the pouch do?','protects the young during early development','marks a map','stores a market’s products','育儿袋保护幼崽并帮助其发育。'),Q('Marsupial is related to a Latin word meaning?','pouch','march','marble','marsupium 的意思是袋子。')]);
P('martial','Martial comes from Latin Martialis, “of Mars,” the Roman god of war; it means related to soldiers, fighting, or martial arts.',C('martial.s1','武术训练','The community centre offers martial arts classes where beginners learn basic kicks, balance, and self-control.','社区中心开设武术课，初学者在那里学习基本踢法、平衡和自我控制。','The community centre offers / martial arts classes / where beginners learn / basic kicks, balance, and self-control.','martial 修饰 arts，martial arts 指武术或格斗训练。','踢法和平衡训练属于武术课程。'),M('The brochure called chess a martial art even though the class involved no fighting, combat practice, or physical technique.','The brochure called karate a martial art because it teaches combat techniques and physical discipline.','不含格斗或身体训练的棋类活动不是武术。'),[Q('Martial arts are related to?','fighting techniques and physical discipline','maple wood and sculpture','wedding registration','martial arts 指武术或格斗技巧。'),Q('What do beginners practise at the centre?','kicks, balance, and self-control','market markup and sales','marshland ecology only','课程教授踢法、平衡和自我控制。'),Q('Martial is historically related to the Roman god?','Mars','Mercury','Jupiter','Martialis 与罗马战神马尔斯有关。'),Q('Which phrase uses martial naturally?','martial law','marital combat','martially marriage','martial law 是与军事相关的固定表达。','collocation')]);
P('martin','Martin is the established English name of a small swallow-like bird, commonly recognized by its forked tail.',C('martin.s1','鸟类观察','A martin circled above the river and returned to its nest beneath the old stone bridge.','一只燕子在河面上盘旋，随后回到老石桥下的巢里。','A martin circled / above the river / and returned to its nest / beneath the old stone bridge.','martin 作可数名词，指一种小型燕类；a martin 表一只鸟。','飞行与桥下筑巢符合该鸟类义。'),M('The field guide identified the martin as a large sea fish with a long bill.','The field guide identified the martin as a small fork-tailed bird nesting under the bridge.','martin 在此指燕类小鸟，不是长吻海鱼。'),[Q('A martin is a small?','bird','stone building','marsh plant','martin 指一种小型鸟类。'),Q('Where did the bird return?','to a nest under the bridge','to a marketplace stall','to the middle of a lunar calendar','它回到老石桥下的巢。'),Q('Which feature is associated with this martin?','a forked tail','a pouch for its young','a long fish bill','词条描述这种鸟有分叉尾。'),Q('Which habitat appears in the example?','a river bridge','an indoor marquee','a dry desert','鸟在河边桥下筑巢。')]);
P('martinet','Martinet came from the name of an officer remembered for strict drill and means someone who enforces discipline rigidly and without flexibility.',C('martinet.s1','办公室管理','The new supervisor was a martinet, requiring staff to follow every minor rule even when it slowed urgent work.','新主管是个严苛的纪律执行者，即使细枝末节的规定会拖慢紧急工作，也要求员工一一遵守。','The new supervisor was a martinet / requiring staff to follow every minor rule / even when it slowed / urgent work.','martinet 作可数名词，带批评意味，指不灵活地严守纪律的人。','小规则优先于紧急工作，体现僵化执行纪律。'),M('The team called her a martinet because she happily ignored all rules and allowed everyone to choose any procedure.','The team called her a martinet because she rigidly enforced every rule without allowing exceptions.','随意忽略规则与严苛守纪正相反。'),[Q('A martinet is someone who?','enforces discipline rigidly','avoids every rule','designs a map','martinet 指僵硬严格地执行纪律的人。'),Q('What did the supervisor insist on?','following even minor rules','ignoring all procedures','ending the workday early','主管要求员工遵守每一项小规定。'),Q('Martinet usually carries what tone?','critical or disapproving','warmly affectionate','purely scientific','该词常带批评意味。','register'),Q('Which person could be called a martinet?','a manager who permits no exceptions to trivial rules','a leader who adapts rules to urgent needs','a colleague who rarely gives instructions','对琐碎规则不许例外的人符合 martinet。')]);
P('martyr','Martyr came through Greek and Latin for “witness”; it can mean someone killed for beliefs, a person who theatrically stresses suffering, or the verb to kill for beliefs.',[C('martyr.s1','历史纪念','The memorial honours a journalist who was killed because she refused to abandon her political beliefs.','纪念碑悼念一名记者，她因拒绝放弃政治信念而被杀害。','The memorial honours / a journalist / who was killed / because she refused to abandon her political beliefs.','martyr 作名词，指因宗教或政治信念被杀的人。','死亡原因直接关联她坚持的信念，符合 s1。'),C('martyr.s2','日常抱怨','He made a martyr of himself over a minor household chore, repeatedly reminding everyone how much he had suffered.','他为一件小家务把自己说成受苦者，反复提醒大家自己有多辛苦。','He made a martyr of himself / over a minor household chore / repeatedly reminding everyone / how much he had suffered.','口语义常带夸张或自怜色彩，指反复强调自己受苦。','小事被反复描述成巨大牺牲，符合 s2。'),C('martyr.s3','历史叙述','The chronicle says the ruler martyred the dissident for refusing to renounce her faith.','编年史称，统治者因异见者拒绝放弃信仰而将她处死，使其成为殉道者。','The chronicle says / the ruler martyred the dissident / for refusing / to renounce her faith.','martyr 可作及物动词，历史语境指因信仰或政治立场杀害某人。','处死的原因是拒绝弃信，符合 s3。')],M('The biography called her a martyr even though she survived safely and was never persecuted for her beliefs.','The biography called her a martyr because she was killed for refusing to renounce her beliefs.','未受迫害且平安生还不符合因信念被杀的义项。'),[Q('A martyr in the historical sense is someone?','killed because of religious or political beliefs','who wins a market competition','who designs a marquee','martyr 指因信仰或政治立场被杀害的人。'),Q('Someone who makes a martyr of himself may be?','exaggerating how much he suffers','quietly refusing all attention','leading a bird survey','口语义常含夸张、自怜。'),Q('In the chronicle, the ruler martyred the dissident by?','killing her for her faith','appointing her to office','asking her to draw a map','动词义表示因信念处死某人。'),Q('What did the journalist refuse to do?','abandon her political beliefs','write a manuscript','cross a marsh','她因坚持政治信念而遭杀害。')]);
P('martyrdom','Martyrdom combines martyr and -dom and names death for a cause or, more broadly, severe suffering endured for it.',C('martyrdom.s1','宗教史','The exhibit explains the martyrdom of early believers who were executed for refusing to renounce their faith.','展览介绍了早期信徒殉教的经历，他们因拒绝放弃信仰而被处决。','The exhibit explains / the martyrdom of early believers / who were executed / for refusing to renounce their faith.','martyrdom 作不可数名词，指因信仰殉难或为事业承受巨大苦难。','信徒因不弃信而被处决，符合 s1。'),M('The museum described the peaceful picnic as martyrdom even though nobody suffered or faced danger.','The museum described the believers’ execution for their faith as martyrdom.','没有苦难或危险的野餐不属于殉难。'),[Q('Martyrdom can refer to?','death or great suffering for a cause','a wedding celebration','a bird’s nest','martyrdom 指为信仰或事业受难。'),Q('Why were the believers executed?','they refused to renounce their faith','they sold goods at a market','they forgot a map','他们拒绝放弃信仰而遭处决。'),Q('Which word is formed with the suffix -dom?','martyrdom','marquee','marlin','martyr 加 -dom 构成 martyrdom。','word-formation'),Q('Which situation is not martyrdom?','an uneventful picnic with no hardship','being killed for one’s beliefs','enduring severe suffering for a cause','普通野餐没有殉难或重大苦难。')]);
P('marvel','Marvel came through Old French merveille from Latin mirabilia (“wondrous things”); it means a wonderful thing or to feel amazement.',[C('marvel.s1','工程奇观','The suspension bridge is a marvel of engineering, spanning the bay with unusually slender supports.','这座悬索桥是工程奇观，以异常纤细的支撑跨越海湾。','The suspension bridge is / a marvel of engineering / spanning the bay / with unusually slender supports.','marvel 作可数名词，a marvel of... 表示令人惊叹的事物。','桥梁设计令人赞叹，符合 s1。'),C('marvel.s2','参观感叹','Visitors marvelled at the ancient mosaic, whose tiny coloured stones had survived for centuries.','游客们对这幅古代马赛克啧啧称奇，因为细小的彩石保存了几个世纪。','Visitors marvelled at / the ancient mosaic / whose tiny coloured stones / had survived for centuries.','marvel 作不及物动词，常用 marvel at something 表示惊叹、赞赏。','游客对保存完好的艺术品感到惊叹。')],M('Visitors marvelled at the bridge by finding it completely ordinary and showing no surprise or admiration.','Visitors marvelled at the bridge because its design and span impressed them.','毫无惊奇或赞赏不能称为 marvel at。'),[Q('A marvel of engineering is?','something that inspires wonder','a minor error in a manuscript','a type of marital form','marvel 名词指令人惊叹的事物。'),Q('Visitors marvelled at the mosaic means they?','felt admiration and wonder','sold it at a marketplace','marked it with a pen','marvel at 表示对某物惊叹。'),Q('Which phrase is natural?','marvel at the ancient design','marvel the design at','marvel for the design at','marvel 作动词常接 at。','collocation'),Q('What had survived for centuries?','the mosaic’s coloured stones','the bridge’s marketing team','a marrow meal','马赛克的彩石保存了数百年。')]);
P('marvellous','Marvellous is the British spelling of marvelous and describes something that causes great pleasure or admiration.',C('marvellous.s1','旅行评价','We had a marvellous view of the harbour from the hill, with every boat visible in the clear evening light.','从山上望去，港口景色美极了，清朗的傍晚光线下每艘船都清晰可见。','We had / a marvellous view of the harbour / from the hill / with every boat visible.','marvellous 作形容词修饰 view；英式拼写包含双 l。','景色令人赞叹，符合 s1。'),M('They called the view marvellous even though fog hid the harbour and no boat could be seen.','They called the view marvellous because the clear light revealed the entire harbour.','景色被浓雾遮住，不支持“美妙”的评价。'),[Q('A marvellous view is?','wonderfully pleasing or impressive','difficult to see because of fog','a formal lunch','marvellous 表示令人愉快或赞叹的。'),Q('What could visitors see from the hill?','the harbour and its boats','a hidden manuscript','a dry marsh','傍晚能清楚看见港口里的船。'),Q('Which spelling is British English?','marvellous','marvelous','marvellos','英式拼写为 marvellous。','spelling'),Q('Which phrase is natural?','a marvellous performance','a marvellous of performance','marvellously performance','marvellous 是形容词，可修饰 performance。','grammar')]);
P('marvelous','Marvelous is the American spelling of marvellous and means wonderfully good or capable of causing surprise.',[C('marvelous.s1','产品评价','The repair was marvelous: the old radio worked again, and the technician explained the fix in plain language.','这次维修太出色了：旧收音机重新工作，技师还用浅白语言解释了修理过程。','The repair was marvelous / the old radio worked again / and the technician / explained the fix in plain language.','marvelous 作形容词可评价质量极好、令人满意。','收音机修好且解释清楚，体现出色效果。'),C('marvelous.s2','惊奇发现','It was marvelous to discover a stream beneath the dry-looking rocks after the long walk.','长途步行后，竟在看似干燥的岩石下发现一条溪流，令人惊奇。','It was marvelous / to discover a stream / beneath the dry-looking rocks / after the long walk.','marvelous 也可表示令人惊讶或不可思议。','干燥岩石下竟有溪流，出乎意料。')],M('The repair was marvelous, but the radio never worked and the technician offered no explanation.','The repair was marvelous because the radio worked again and the technician explained the fix clearly.','设备仍坏且无说明，不支持“出色”的评价。'),[Q('A marvelous repair is?','wonderfully good','too poor to function','a large wetland','marvelous 表示极好、令人满意。'),Q('What made the stream discovery marvelous?','it was unexpected beneath dry-looking rocks','it was marked on every map','it was served at a luncheon','隐藏溪流令人意外。'),Q('Which spelling is common in American English?','marvelous','marvellous','marvelouss','美式拼写 marvelous 为一个 l。','spelling'),Q('Which phrase is grammatical?','a marvelous result','marvelously result','marvelousness result','marvelous 作形容词修饰 result。','grammar')]);
P('marvelously','Marvelously is formed from marvelous plus -ly and means extremely well or in a way that causes wonder.',C('marvelously.s1','舞台演出','The orchestra played marvelously despite having only one afternoon to rehearse the difficult new piece.','尽管只有一个下午排练这首难度很高的新曲子，乐团仍演奏得精彩极了。','The orchestra played marvelously / despite having only one afternoon / to rehearse / the difficult new piece.','marvelously 作副词修饰 played，描述演奏表现出色。','短时间准备仍演奏精彩，符合 s1。'),M('The orchestra played marvelously, producing a painful, disorganised performance that the audience could not finish hearing.','The orchestra played marvelously, performing the difficult piece with clarity and skill.','糟糕混乱的演奏不能称为 marvelously performed。'),[Q('The orchestra played marvelously means it played?','extremely well','without making any sound','only at lunchtime','marvelously 表示做得非常出色。'),Q('What made the performance notable?','the orchestra rehearsed only briefly but played well','the piece had no music','the hall was a marsh','例句突出短暂排练后仍演奏精彩。'),Q('Marvelously modifies which word in the sentence?','played','orchestra','afternoon','marvelously 是副词，修饰 played。','grammar'),Q('Which sentence uses marvelously correctly?','The plan worked marvelously.','The marvelously plan worked.','The plan marvelouslyly worked.','副词 marvelously 可修饰 worked。','grammar')]);
P('Marxism','Marxism is named for Karl Marx and refers to political and economic ideas based on his analysis of class, capital, and historical change.',[C('Marxism.s1','思想史课程','The lecture introduced Marxism as a set of ideas about class relations, ownership, and economic change.','讲座把马克思主义介绍为一套有关阶级关系、所有权和经济变化的思想。','The lecture introduced Marxism / as a set of ideas / about class relations, ownership, / and economic change.','Marxism 作专有名词，首字母大写，指以马克思思想为基础的理论体系。','主题涵盖阶级、所有权与经济变化。'),C('Marxism.s2','社会分析','In the essay, the researcher used Marxism to analyse how class and ownership shaped the history of the factory town.','在论文中，研究者用马克思主义分析阶级和所有权如何塑造工厂城镇的历史。','In the essay / the researcher used Marxism / to analyse how class and ownership / shaped the history of the factory town.','Marxism 也指运用该理论分析历史或社会的研究方法。','理论被用于解释具体社会历史，符合 s2。')],M('The article called its approach Marxism even though it rejected analysis of class, capital, and economic relations entirely.','The article used Marxism to examine class, capital, and economic relations.','完全拒绝相关分析不符合此处对 Marxism 的定义。'),[Q('Marxism is based on the writings of?','Karl Marx','Charles Darwin','a medieval field marshal','Marxism 以卡尔·马克思的著作为基础。'),Q('Which topics are central to the definition?','class, ownership, and economic change','marsh plants and maples','marital status and lunch','词条说明涉及阶级关系、所有权和经济变化。'),Q('A researcher using Marxism is applying?','ideas to analyse history or society','a method for measuring sound','a technique for making marble','Marxism 可指运用该理论作社会分析。'),Q('Why is the M capitalized?','it is named for Karl Marx','all abstract nouns are capitalized','it begins a sentence in the middle','Marxism 是由人名构成的专有名称。','capitalization')]);
P('Marxist','Marxist is formed from Marx plus -ist and means based on Marx’s theories or a person who supports Marxism.',[C('Marxist.s1','理论分析','The historian offered a Marxist interpretation of the strike, focusing on workers’ conditions and control of production.','这位历史学家对罢工作出马克思主义解读，重点分析工人的处境和生产控制权。','The historian offered / a Marxist interpretation of the strike / focusing on workers’ conditions / and control of production.','Marxist 作形容词修饰 interpretation，首字母大写。','分析从阶级和生产关系出发，符合理论义 s1。'),C('Marxist.s2','人物介绍','The article describes the economist as a Marxist who studies ownership and class relations.','文章把这位经济学家描述为一名马克思主义者，研究所有权和阶级关系。','The article describes / the economist as a Marxist / who studies ownership / and class relations.','Marxist 作可数名词，指支持或采用马克思主义的人。','人物研究马克思主义关注的议题。')],M('The essay is Marxist even though it explicitly rejects every Marxist idea and never considers class or ownership.','The essay is Marxist because it interprets the strike through class relations and control of production.','拒绝相关理论且不谈阶级或所有权，与 Marxist 解读相反。'),[Q('A Marxist interpretation may focus on?','class relations and control of production','lunar calendars and maracas','marriage certificates','例句按阶级关系和生产控制分析罢工。'),Q('A Marxist can be?','a person who supports or studies Marxism','a kind of marsh bird','a market stall','Marxist 作名词指马克思主义者。'),Q('Which phrase uses Marxist as an adjective?','a Marxist theory','a Marxist who attended','the Marxist’s notebook only','a Marxist theory 中 Marxist 修饰 theory。','grammar'),Q('Which suffix forms Marxist from Marx?','-ist','-ness','-ly','-ist 常构成人或思想立场的名称。','word-formation')]);
P('mascot','Mascot came through French mascotte from Provençal mascoto, “charm”; it is a figure adopted to represent a group and believed to bring luck.',C('mascot.s1','球队活动','The school chose a fox as its mascot, and students wore the costume during the annual sports final.','学校选狐狸作为吉祥物，学生在年度体育决赛期间穿上了相关服装。','The school chose a fox / as its mascot / and students wore the costume / during the annual sports final.','mascot 作可数名词，代表学校或团队的象征形象。','狐狸形象代表学校并出现在赛事中，符合 s1。'),M('The team introduced a mascot that represented a rival school and was never used at its own events.','The team introduced a mascot that represented its school and appeared at its games.','代表对手且不用于本队活动，不符合该队吉祥物的功能。'),[Q('A school mascot is a figure that?','represents the school or team','measures a student’s exam mark','maps a coastline','mascot 是代表团体的象征形象。'),Q('What animal did the school choose?','a fox','a marlin','a marsupial’s pouch','例句说明学校选了狐狸。'),Q('Where did students wear the costume?','at the sports final','inside the lost-and-found','during a lunar eclipse','学生在年度体育决赛穿着吉祥物服装。'),Q('Mascot originally carried the idea of a?','charm or lucky figure','marriage certificate','written manuscript','词源可追溯到表示护符的词。')]);
P('masculine','Masculine came through French from Latin masculinus and can describe traditionally male-associated qualities, grammatical gender, or that gender category.',[C('masculine.s1','服装风格','The designer used a traditionally masculine cut for the jacket, while avoiding claims that the style suited only men.','设计师采用了传统上偏男性化的剪裁，同时避免声称这种风格只适合男性。','The designer used / a traditionally masculine cut / for the jacket / while avoiding claims that it suited only men.','masculine 作形容词可描述传统上与男性关联的风格；这不是对性别的硬性规定。','说明传统风格关联，同时指出并非仅限某性别。'),C('masculine.s2','语法类别','In Spanish, “el libro” uses a masculine article because libro belongs to the masculine grammatical gender.','在西班牙语中，el libro 使用阳性冠词，因为 libro 属于语法阳性类别。','In Spanish / “el libro” uses a masculine article / because libro belongs / to the masculine grammatical gender.','语法义 masculine 指名词的语法性别类别，不等同于真实人物性别。','例句涉及西语名词语法类别。'),C('masculine.s3','语法术语','The lesson compared the masculine and feminine forms of several adjectives in the language.','课程比较了该语言中若干形容词的阳性形式和阴性形式。','The lesson compared / the masculine and feminine forms / of several adjectives / in the language.','masculine 可作名词，指语法阳性或传统男性气质这一概念。','与 feminine 对照的是一种语法性别类别。')],M('The grammar book called “libro” masculine because it referred to a man rather than because of its noun class.','The grammar book called “libro” masculine because Spanish assigns it to the masculine noun class.','语法性别由词类系统决定，不是名词所指物体的实际性别。'),[Q('A masculine jacket style is?','traditionally associated with men, without being exclusive to them','a grammatical error in every language','a type of marine animal','masculine 可指传统上与男性关联的风格。'),Q('In Spanish grammar, masculine describes?','a noun-class category','the actual sex of every object named','a person’s marital status','语法阳性是词类类别，不代表物体性别。'),Q('Why is “libro” masculine in the example?','Spanish assigns it to that grammatical class','it names a male person','it is made from marble','句子说明这是西班牙语的语法类别。'),Q('Which contrast is grammatical?','masculine and feminine forms','masculine and marvellous forms','masculine and marketplace forms','语法中常对比阳性和阴性形式。','collocation')]);
P('maser','Maser is an acronym for microwave amplification by stimulated emission of radiation and names a device that produces coherent microwaves.',C('maser.s1','射电天文','The observatory used a maser to generate a stable microwave signal for precise astronomical measurements.','天文台使用脉泽产生稳定的微波信号，以进行精密天文测量。','The observatory used / a maser / to generate a stable microwave signal / for precise astronomical measurements.','maser 作可数名词，指通过受激辐射放大微波的仪器。','稳定微波信号用于精确测量，符合 s1。'),M('The engineer called the device a maser even though it produced only ordinary visible light and no microwaves.','The engineer called the device a maser because it amplified a coherent microwave beam.','只产生可见光、没有微波的设备不符合 maser 定义。'),[Q('A maser produces or amplifies?','coherent microwaves','marble dust','visible paint marks','maser 用受激辐射产生或放大微波。'),Q('What signal did the observatory need?','a stable microwave signal','a maraca rhythm','a lunch announcement','设备用于产生稳定的微波信号。'),Q('Maser is an acronym referring to?','microwave amplification by stimulated emission of radiation','map arrangement by sea and river','mass production after sunrise','maser 是该物理术语首字母缩写。'),Q('Which field may use masers for precise signals?','astronomy','marriage counselling','marsh gardening','天文观测会利用稳定微波信号。')]);
P('mask','Mask entered English through French masque, perhaps from Italian; it can be a face covering, a concealment, or the verb to hide something.',[C('mask.s1','防护用品','The laboratory worker wore a fitted mask while handling the dusty sample in the ventilation room.','实验室工作人员在通风室处理多尘样本时戴上了合适的口罩。','The laboratory worker wore / a fitted mask / while handling the dusty sample / in the ventilation room.','mask 作可数名词，指覆盖脸部以保护、伪装或表演的物品。','口罩用于防尘，符合 s1。'),C('mask.s2','情绪隐藏','His cheerful mask slipped when the meeting ended and he admitted how worried he had been.','会议结束后，他开朗的假面松动了，他承认自己一直非常担心。','His cheerful mask slipped / when the meeting ended / and he admitted / how worried he had been.','mask 可比喻掩饰真实感情的外在表现。','表面开朗掩盖了真实担忧，符合 s2。'),C('mask.s3','气味掩盖','Strong coffee masked the smell of smoke in the corridor but did not remove its source.','浓咖啡的气味掩盖了走廊里的烟味，却没有消除烟味的来源。','Strong coffee masked / the smell of smoke / in the corridor / but did not remove its source.','mask 作及物动词，表示使气味、事实或感受不易被察觉。','咖啡气味遮住烟味但未消除来源，符合 s3。')],M('Coffee masked the smoke smell by making it stronger and easier for everyone to detect.','Coffee masked the smoke smell by covering it with a stronger coffee aroma.','让烟味更明显不是掩盖气味。'),[Q('A fitted mask in a dusty lab is worn to?','cover and protect the face','mark a manuscript','produce microwaves','口罩可防止粉尘进入呼吸道。'),Q('A cheerful mask that slips reveals?','the real feelings beneath it','a physical map of the face','a person’s market price','比喻义 mask 指掩饰真实情绪的外表。'),Q('Coffee masked the smoke smell means it?','covered the smell without removing its source','eliminated the source of the smoke','made the smoke brighter','mask 可表示掩盖气味但不消除来源。'),Q('Which is a verb use of mask?','She masked her disappointment with a smile.','She wore a mask at the lab.','The mask was on the table.','masked 在此是动词，表示掩饰情绪。','grammar')]);
P('mason','Mason comes through Old French maçon and means a worker who builds with stone or brick; it can also be a verb meaning to build with masonry.',[C('mason.s1','建筑修复','A mason replaced the cracked stones in the old wall and matched the mortar to the original joints.','石匠更换了旧墙上开裂的石块，并让灰浆与原有接缝相配。','A mason replaced / the cracked stones / in the old wall / and matched the mortar / to the original joints.','mason 作可数名词，指砌石或砌砖的建筑工人。','石匠修复石墙和灰缝，符合 s1。'),C('mason.s2','施工说明','The crew will mason the damaged garden wall with reclaimed brick next week.','施工队下周将用回收砖块砌修受损的花园围墙。','The crew will mason / the damaged garden wall / with reclaimed brick / next week.','mason 也可作动词，表示用砖石砌筑或加固。','用回收砖修墙体现砌筑动词义。')],M('The mason repaired the stone wall using only loose paper and no brick, stone, or mortar.','The mason repaired the stone wall with fitted blocks and fresh mortar.','石匠的工作是砌筑砖石，不是只用纸张。'),[Q('A mason is a worker who builds with?','stone or brick','maps or manuscripts','margarine or marrow','mason 指石匠或泥瓦匠。'),Q('What did the mason repair?','the cracked stones in an old wall','a lunar calendar','a maraca','例句中石匠修复旧墙。'),Q('“The crew will mason the wall” uses mason as?','a verb meaning build with masonry','a noun for the wall’s owner','an adjective meaning marital','mason 可作动词表示砌筑。'),Q('Which material did the crew use?','reclaimed brick','marlin scales','marsh water','施工使用回收砖块。')]);
P('masonry','Masonry comes from mason and refers to stone or brick construction and the parts of a building made from those materials.',C('masonry.s1','建筑检查','The inspector examined the masonry around the arch and found several loose bricks that needed repair.','检查员查看了拱门周围的砌体，发现几块松动的砖需要修补。','The inspector examined / the masonry around the arch / and found / several loose bricks that needed repair.','masonry 作不可数名词，指砖石砌筑结构或砌体。','松动砖块属于建筑砌体的一部分。'),M('The building’s masonry consisted entirely of loose cloth curtains with no stone, brick, or mortar.','The building’s masonry consisted of stone and brick held together with mortar.','布帘不是砖石砌体。'),[Q('Masonry is construction made from?','stone or brick','glass marbles only','cloth and paper','masonry 指砖石建筑和砌体。'),Q('What did the inspector find?','loose bricks near the arch','a marlin in the wall','a wedding marquee','拱门周围发现松动砖块。'),Q('Masonry is related to which worker?','a mason','a mascot','a martinet','mason 是从事砖石砌筑的人。'),Q('Which phrase is natural?','masonry wall','masonry of lunch loudly','masonryly arch','masonry wall 是自然搭配。','collocation')]);
P('mass','Mass comes through Latin massa from Greek maza (“lump”); it can mean a lump, a crowd, physical quantity of matter, a Catholic service, or large-scale activity.',[C('mass.s1','材料形态','A mass of wet clay stuck to the bottom of the bucket after the potter finished shaping the bowl.','陶艺家捏好碗后，一团湿黏土粘在桶底。','A mass of wet clay / stuck to the bottom / of the bucket / after the potter finished shaping the bowl.','mass 作可数名词，a mass of 表示一大团无规则物质。','黏土聚成一团，符合 s1。'),C('mass.s2','人群聚集','A mass of spectators gathered outside the stadium when the final match sold out.','决赛门票售罄后，大批观众聚集在体育场外。','A mass of spectators gathered / outside the stadium / when the final match / sold out.','a mass of people 可指大量人群。','许多人聚集，符合 s2。'),C('mass.s3','物理测量','The experiment measured the mass of each sample before heating it.','实验在加热前测量了每份样品的质量。','The experiment measured / the mass of each sample / before heating it.','物理学 mass 指物体所含物质的量，不等同于重量。','样品加热前记录物质质量，符合 s3。'),C('mass.s4','宗教仪式','The family attended Mass on Sunday morning at the Catholic church.','这家人周日早晨到天主教堂参加弥撒。','The family attended Mass / on Sunday morning / at the Catholic church.','Mass 首字母大写时可指天主教的主要礼仪弥撒。','天主教堂的礼仪活动符合 s4。')],M('The physicist said mass means how loud an object sounds when struck.','The physicist said mass measures the amount of matter in an object.','声音响度不是物理学中的质量。'),[Q('A mass of clay is?','a large lump of material','a thin printed margin','a type of tent','mass 可指一大团物质。'),Q('A mass of spectators is?','a large crowd','one person alone','a map symbol','a mass of people 表示大量人群。'),Q('In physics, mass measures?','the amount of matter in an object','the volume of its sound','the number of pages in a manuscript','质量衡量物体所含物质的量。'),Q('In a Catholic church, Mass is?','a central religious service','a measurement of a crowd','a pile of clay','Mass 大写时可指弥撒礼仪。')]);
P('mass-produced','Mass-produced combines mass and produced and describes goods manufactured in very large quantities, usually with similar standardised units.',C('mass-produced.s1','工厂生产','The company sells mass-produced water bottles made on an automated line, so each has the same shape and capacity.','公司出售在自动化生产线上制造的大批量水瓶，因此每只瓶子的形状和容量相同。','The company sells / mass-produced water bottles / made on an automated line / so each has the same shape and capacity.','mass-produced 作复合形容词修饰 products，连字符保留。','自动化生产大量标准化水瓶，符合 s1。'),M('The bottles were mass-produced even though an artisan made each one individually by hand as a unique object.','The bottles were mass-produced on an automated line in large, nearly identical batches.','逐件手工制作的独一件商品不是 mass-produced。'),[Q('Mass-produced goods are made?','in very large quantities','one unique item at a time by hand','only for a wedding','mass-produced 表示大批量生产的。'),Q('Why do the bottles look alike?','they come from a standardised automated line','each was designed by a different artist','they were collected from marshland','流水线生产使每只瓶子形状和容量相似。'),Q('Which spelling matches the assigned headword?','mass-produced','massproduced','mass produce-ed','复合形容词应写作 mass-produced。','spelling'),Q('Which item is most likely mass-produced?','standard bottles made in huge batches','a one-of-a-kind sculpture carved by hand','a unique handwritten manuscript','大量标准化制造的瓶子最符合该词。')]);
P('massacre','Massacre came into English through French, with deeper origin uncertain; it means the violent killing of many defenceless people and can informally mean a severe defeat.',[C('massacre.s1','历史纪念','The museum documents the massacre of civilians and preserves testimony from survivors and their families.','博物馆记录了平民遭屠杀的事件，并保存幸存者及其家人的证词。','The museum documents / the massacre of civilians / and preserves testimony / from survivors and their families.','massacre 作可数或不可数名词，指大量手无寸铁者遭暴力杀害。','平民遭大规模杀害，符合 s1。'),C('massacre.s2','比赛评论','The newspaper said the visiting team massacred its opponent, winning by a record margin in the final.','报纸称客队在决赛中大胜对手，以创纪录的分差获胜。','The newspaper said / the visiting team massacred its opponent / winning by a record margin / in the final.','口语或新闻夸张用法中，massacre 可表示彻底击败对手。','体育比赛中的悬殊比分属于比喻义 s2。')],M('The report called it a massacre even though no one was injured or killed and the contest ended in a tie.','The report called it a massacre because many defenceless civilians were violently killed.','无人伤亡且平局不符合大屠杀或彻底击败的语境。'),[Q('A massacre in the historical sense is?','the violent killing of many defenceless people','a small difference in a game','a medical massage','massacre 指大规模暴力杀害。'),Q('In sports reporting, a team massacred its opponent means it?','defeated them overwhelmingly','played to a scoreless tie','helped them win','夸张用法表示彻底大胜。'),Q('What does the museum preserve?','testimony from survivors and families','a mass of clay','marital forms','博物馆保存幸存者及家属的证词。'),Q('Which use is figurative and informal?','The team massacred its rival in the final.','Civilians were killed in a documented massacre.','The museum records a historical massacre.','比赛大胜的用法是夸张比喻义。','register')]);
P('massage','Massage came through French from Greek massein (“to knead”); it names rubbing and pressing the body, the act itself, or figuratively manipulating facts.',[C('massage.s1','康复护理','After the long race, the athlete received a gentle leg massage to ease muscle tension.','长跑结束后，运动员接受了轻柔的腿部按摩以缓解肌肉紧张。','After the long race / the athlete received / a gentle leg massage / to ease muscle tension.','massage 作名词，指按压揉动身体以放松或缓解不适。','腿部肌肉被按摩以减轻紧张，符合 s1。'),C('massage.s2','理疗动作','The therapist massaged the patient’s shoulder carefully, avoiding the bruised area.','治疗师小心按摩患者肩部，避开了瘀伤部位。','The therapist massaged / the patient’s shoulder carefully / avoiding / the bruised area.','massage 作及物动词，massage a body part 表示按摩该部位。','治疗师用手按揉肩部，符合 s2。'),C('massage.s3','数据粉饰','The report’s authors massaged the figures by excluding the months with the worst results.','报告作者通过剔除结果最差的几个月来粉饰数据。','The report’s authors massaged the figures / by excluding the months / with the worst results.','比喻义 massage figures/data 指选择性改动或呈现数据，使结果显得更好。','排除差结果以制造更好印象，符合 s3。')],M('The analyst massaged the figures by including every poor result and showing the unaltered full dataset.','The analyst massaged the figures by selectively omitting poor results to make performance look better.','完整呈现全部结果不属于粉饰数据。'),[Q('A leg massage involves?','rubbing and pressing muscles','writing notes in a page margin','measuring a person’s mass','按摩通过揉按身体放松肌肉。'),Q('The therapist massaged the shoulder means the therapist?','rubbed and pressed it carefully','covered it with a mask','marked it with a pen','massage 作动词表示按摩。'),Q('To massage figures is to?','manipulate their presentation to look better','give a person a body treatment','measure physical mass accurately','比喻义指粉饰或操纵数据呈现。'),Q('Why was the report’s dataset misleading?','the worst months were excluded','the figures were fully transparent','the authors preserved every result','剔除差结果使数据显得更好看。')]);
P('masses','Masses is the plural of mass and can refer to large numbers of people or things considered together.',C('masses.s1','公共集会','The masses filled the square to hear the candidates explain their plans for public transport.','大批民众挤满广场，聆听候选人说明公共交通计划。','The masses filled the square / to hear the candidates / explain their plans / for public transport.','masses 作复数名词，常指数量庞大的普通人群。','广场里聚集了许多民众，符合 s1。'),M('The article said the masses attended, although only one person appeared in the square.','The article said the masses attended because a very large crowd filled the square.','单独一人不构成 masses 所说的大量人群。','plural'),[Q('The masses in the square were?','a large number of people','one visitor alone','a set of marble stones','masses 可指大批人群。'),Q('What did the crowd come to hear?','plans for public transport','a recipe for margarine','a lunar calendar','候选人说明公共交通计划。'),Q('Masses is the plural form of?','mass','mast','marsh','masses 是 mass 的复数形式。','plural'),Q('Which phrase is natural?','the masses gathered in the square','a masses gathered in the square','masses of one person','masses 常指人数众多的一群人。','grammar')]);
P('massif','Massif came from French massif, “solid or compact”; it names a compact block or group of mountains standing apart from nearby terrain.',[C('massif.s1','山地地貌','The granite massif rose above the surrounding plain as one broad, connected block of high ground.','这片花岗岩山块像一整块相连的高地，从周围平原上耸起。','The granite massif rose / above the surrounding plain / as one broad, connected block / of high ground.','massif 作可数名词，指与周围地形相对独立的山体或山群。','连成一体的高地从平原中突起，符合 s1。'),C('massif.s2','地形描述','A high massif dominated the valley, although its rounded summit was lower than the neighbouring peak.','一座高大的山丘群主宰着山谷景观，尽管它圆缓的峰顶低于邻近山峰。','A high massif dominated the valley / although its rounded summit / was lower than / the neighbouring peak.','massif 也可泛指宽阔隆起的高地或山丘。','宽阔高地成为谷地的主要地形特征，符合 s2。')],M('The geologist called the isolated mountain block a massif, although the land was completely flat.','The geologist called the isolated block of high, connected mountains a massif.','完全平坦的土地没有构成山块或高地。'),[Q('A massif is a?','compact block or group of mountains','low marsh covered by reeds','mass-produced object','massif 指相对独立的山体或山群。'),Q('What surrounded the granite massif?','a plain','a marketplace','a maritime fleet','例句说山体从周围平原上耸起。'),Q('Which feature fits a massif?','a broad connected area of high ground','a flat floor mat','a single thin tree branch','massif 通常指宽阔连成一体的高地。'),Q('Massif was borrowed from?','French','Old English','Latin through Italian only','massif 来自法语。')]);
P('massive','Massive came through French from Latin massa (“lump”) and describes something very large and heavy or a very great amount.',C('massive.s1','建筑工程','A massive stone arch spans the river, supported by piers sunk deep into the bedrock.','一座巨大的石拱桥横跨河流，由深深嵌入基岩的桥墩支撑。','A massive stone arch / spans the river / supported by piers / sunk deep into the bedrock.','massive 作形容词，强调体积或重量很大。','石拱桥规模庞大并由厚重桥墩支撑，符合 s1。'),M('The crew lifted the massive stone arch with two fingers because it weighed almost nothing.','The crew used a crane to lift the massive stone arch because it was extremely heavy.','几乎没有重量的物体不符合 massive 的笨重含义。'),[Q('A massive stone arch is?','very large and heavy','a tiny glass marble','a mild lunch','massive 描写体积或重量巨大。'),Q('What supports the arch?','piers sunk into bedrock','a paper margin','a marshy path','桥墩深嵌基岩以支撑石拱。'),Q('Which amount could be massive?','a very great quantity','a single grain only','an unchanged measurement','massive 也可形容数量巨大。'),Q('Which adjective is closest to massive here?','enormous','marginal','marital','enormous 同样表示巨大。')]);
P('mast','Mast is an old nautical word for a ship’s upright spar and can also mean a tall pole for a flag or antenna.',[C('mast.s1','航海维修','The crew inspected the mast for cracks before raising the sail for the afternoon crossing.','船员在下午横渡前检查桅杆是否有裂缝，然后升起船帆。','The crew inspected the mast / for cracks / before raising the sail / for the afternoon crossing.','mast 作可数名词，帆船 mast 是支撑船帆的直立桅杆。','桅杆支撑即将升起的船帆，符合 s1。'),C('mast.s2','船只改装','The workshop will mast the small boat with a new wooden spar before the owner collects it.','船主取船前，修理厂会给小船装上一根新木桅杆。','The workshop will mast the small boat / with a new wooden spar / before the owner collects it.','mast 也可作及物动词，表示给船装上桅杆。','为小船安装桅杆，符合 s2。')],M('The sailor inspected the mast, a horizontal rope lying loose on the deck.','The sailor inspected the mast, the upright spar that supports the sail.','mast 是直立桅杆，不是松散的水平绳索。'),[Q('A ship’s mast is normally?','an upright spar that supports a sail','a horizontal dining table','a small mark in a manuscript','桅杆直立并支撑船帆。'),Q('What did the crew check before sailing?','the mast for cracks','the maraca for a loose seed','the marriage certificate','船员检查桅杆是否开裂。'),Q('To mast a boat is to?','provide it with a mast','remove its sail and mast','measure its mass','mast 可作动词表示装桅杆。'),Q('A flag mast is a tall?','pole','marsh','lunch','mast 也可指旗杆或天线杆。')]);
P('master','Master came through Old French from Latin magister (“chief, teacher”); it can name an expert, a postgraduate degree, a historical authority, a verb meaning learn fully, or a main controlling device.',[C('master.s1','技艺评价','After decades at the bench, the violin maker became a master whose instruments were sought by orchestras.','在工作台前劳作数十年后，这位制琴师成为技艺高超的大师，乐团争相订购他的乐器。','After decades at the bench / the violin maker became a master / whose instruments / were sought by orchestras.','master 作可数名词，可指某门艺术或手艺的高手。','高超技艺和作品声誉符合 s1。'),C('master.s2','大学教育','She completed a master’s in marine biology before joining the coastal research institute.','她完成海洋生物学硕士学位后，加入了沿海研究所。','She completed / a master’s in marine biology / before joining / the coastal research institute.','a master’s 表示学士之后的硕士学位。','完成研究生学位符合 s2。'),C('master.s3','历史语境','The archive describes the household master as the person who controlled servants in that historical system.','档案把家主描述为该历史制度中支配仆役的人。','The archive describes / the household master / as the person / who controlled servants in that historical system.','master 的主人义属历史语境，历史上也涉及奴役关系；现代使用需顾及上下文。','文献讨论历史制度中的控制者，符合 s3。'),C('master.s4','技能学习','It took Maya a year to master the software well enough to teach the advanced course.','玛雅花了一年才熟练掌握这款软件，达到能讲授高级课程的程度。','It took Maya a year / to master the software / well enough / to teach the advanced course.','master 作及物动词，表示充分学会并熟练运用。','熟练到能够授课，符合 s4。'),C('master.s5','总控设备','The master switch controls the lights in every room of the exhibition hall.','总控开关控制展览大厅每个房间的灯光。','The master switch controls / the lights / in every room / of the exhibition hall.','master 作定语表示主要、总控或支配全局的。','一个总开关控制全部灯光，符合 s5。')],M('Maya mastered the software by never learning how any of its functions worked.','Maya mastered the software by learning its functions thoroughly and using them confidently.','完全没有学会功能与“掌握”相矛盾。'),[Q('A master violin maker is?','a person with exceptional skill','a first-year student','a ship’s mast','master 可指技艺高超的人。'),Q('A master’s in biology is?','a postgraduate degree','a maritime vessel','a teacher’s handwritten manuscript','master’s degree 是学士之后的研究生学位。'),Q('To master software is to?','learn it thoroughly and use it skilfully','install it without opening it','mark its box and throw it away','master 作动词表示掌握技能。'),Q('A master switch usually?','controls a larger system','decorates a single page margin','produces microwave radiation','master 可作定语表示总控的。')]);
P('mastercard','Mastercard is the proper name of an international payment-card network; the ordinary card name is capitalized as a brand.',C('mastercard.s1','付款结账','At checkout, Nia used her Mastercard to pay for the train ticket and received a digital receipt.','结账时，妮娅用万事达卡支付火车票，并收到了电子收据。','At checkout / Nia used her Mastercard / to pay for the train ticket / and received a digital receipt.','Mastercard 是品牌专名，按品牌写法大写；可作卡种名称。','用于支付车票符合付款卡网络义。'),M('The receipt says the customer paid with mastercard, treating the company’s brand name as an ordinary lowercase word.','The receipt says the customer paid with Mastercard, using the brand’s capitalized name.','品牌专名应保留首字母大写。','capitalization'),[Q('Mastercard is the name of a?','payment-card network','marshland bird','marble-building technique','Mastercard 指支付卡网络。'),Q('What did Nia pay for?','a train ticket','a master’s degree','a maraca','她用卡支付火车票。'),Q('How is the brand normally written?','Mastercard','mastercard','MasterCarded','品牌专名使用大写形式 Mastercard。','capitalization'),Q('What did the receipt provide?','a digital record of payment','a maritime map','a music lesson','付款后收到了电子收据。')]);
P('masterful','Masterful combines master and -ful and means highly skilled; it can also mean domineering or overly authoritative.',[C('masterful.s1','舞台演出','The pianist gave a masterful performance, balancing the rapid passages with a controlled, expressive tone.','钢琴家演奏得炉火纯青，在快速乐段与克制而富有表现力的音色间保持了平衡。','The pianist gave / a masterful performance / balancing rapid passages / with a controlled, expressive tone.','masterful 作形容词可褒义地描述技艺高超的表现。','技术难度和表现力兼备，符合 s1。'),C('masterful.s2','管理风格','Her masterful manner left no room for discussion, as she issued orders and dismissed every suggestion.','她专断的作风不给讨论留余地，只顾下达命令并否决所有建议。','Her masterful manner / left no room for discussion / as she issued orders / and dismissed every suggestion.','masterful 也可批评某人专横、自以为有权发号施令。','拒绝讨论且强硬命令体现负面义 s2。')],M('The manager was masterful by inviting open discussion, welcoming disagreement, and refusing to dominate the team.','The manager was masterful in the domineering sense because she rejected discussion and imposed every decision.','开放协作不是此处“专横”的意思。'),[Q('A masterful piano performance is?','performed with great skill','performed without control or practice','a payment-card service','masterful 可称赞技艺高超的演出。'),Q('A masterful manner may be criticized as?','domineering and authoritarian','quietly uncertain','marshy and wet','masterful 也可表示专横。'),Q('Which part of the performance showed skill?','balancing speed with expressive control','forgetting every note','stopping before playing','快速乐段与表现力平衡体现技巧。'),Q('Which sentence uses the negative sense?','He gave masterful orders and allowed no discussion.','She gave a masterful violin recital.','Their masterful repair was precise and elegant.','拒绝讨论、独断发令体现负面义。')]);
P('masterly','Masterly comes from master plus -ly and describes superbly controlled skill; it can also function as an adverb meaning with great skill.',[C('masterly.s1','绘画技法','The restoration team made a masterly repair, matching the missing pigment without obscuring the original brushwork.','修复团队的修补技艺高超，补齐了缺失颜料，又没有遮盖原有笔触。','The restoration team made / a masterly repair / matching the missing pigment / without obscuring the original brushwork.','masterly 作形容词修饰 repair，表示做得巧妙熟练。','修补准确并保留原作细节，符合 s1。'),C('masterly.s2','棋局分析','She handled the endgame masterly, exchanging pieces at exactly the right moment.','她巧妙地处理了棋局残局，在恰当时机交换棋子。','She handled the endgame masterly / exchanging pieces / at exactly the right moment.','masterly 也可作副词，修饰 handled，意为熟练巧妙地。','精准交换棋子显示高超棋艺，符合 s2。')],M('The restorer made a masterly repair by covering the original artwork with careless, mismatched paint.','The restorer made a masterly repair by matching the pigment while preserving the original brushwork.','粗心覆盖原作不属于高超修复。'),[Q('A masterly repair is?','done with superb control and skill','performed carelessly with mismatched materials','a highly paid degree','masterly 形容技艺精湛的修复。'),Q('She handled the endgame masterly means she handled it?','with great skill','without understanding the rules','with a loudspeaker','masterly 作副词表示熟练地。'),Q('What did the restoration team preserve?','the original brushwork','the missing wall outside','the price markup','团队保留了原始笔触。'),Q('Which usage is correct?','a masterly performance','a masterlyly performance','a master performanceful','masterly 可作形容词修饰 performance。','grammar')]);
P('masterpiece','Masterpiece combines master and piece and names a work of the very highest quality, often an artist’s best-known or finest work.',[C('masterpiece.s1','艺术鉴赏','The gallery calls the portrait a masterpiece because its composition, colour, and expression remain striking centuries later.','画廊称这幅肖像画为杰作，因为几个世纪后其构图、色彩和神情仍令人印象深刻。','The gallery calls the portrait / a masterpiece / because its composition, colour, and expression / remain striking.','masterpiece 作可数名词，指质量极高的艺术作品。','持久的艺术表现力支持“杰作”评价。'),C('masterpiece.s2','代表作品','Although the composer wrote dozens of symphonies, critics often regard the final one as her masterpiece.','尽管这位作曲家创作了数十部交响曲，评论家通常仍把最后一部视为她的代表作。','Although the composer wrote dozens of symphonies / critics often regard / the final one / as her masterpiece.','someone’s masterpiece 指某人最出色或最具代表性的作品。','在她众多作品中被视为最佳，符合 s2。')],M('Critics called the damaged sketch a masterpiece even though it was unfinished, careless, and of no artistic merit.','Critics called the carefully composed portrait a masterpiece because of its exceptional quality.','毫无艺术价值且粗心未完成的草图不支持杰作评价。'),[Q('A masterpiece is?','a work of the very highest quality','a routine receipt','a small floor mat','masterpiece 指杰作或名著。'),Q('What makes the portrait a masterpiece?','its composition, colour, and expression remain striking','it was mass-produced on an assembly line','it contains no artistic choices','艺术构图与表现力支撑赞誉。'),Q('Her masterpiece is likely to be?','her finest or most representative work','her least successful draft','the only work she has never made','one’s masterpiece 指最出色的作品。'),Q('Which word forms the compound masterpiece?','master + piece','marsh + land','marry + age','masterpiece 是 master 与 piece 的复合词。','word-formation')]);
P('mastership','Mastership combines master and -ship and means the state of having mastered a craft or the office or authority of a master.',C('mastership.s1','工艺传承','Her mastership of traditional bookbinding was evident in the clean joints and durable covers she taught apprentices to make.','她对传统装帧技艺的精通体现在整洁的接缝和耐用封面上，她还教徒弟制作这些作品。','Her mastership / of traditional bookbinding / was evident / in the clean joints and durable covers.','mastership 作抽象名词，指熟练掌握某项技艺或大师身份。','作品质量和教学体现精湛掌握。'),M('The craft guild recognised his mastership even though he had never learned the trade or completed a single binding.','The craft guild recognised his mastership after he demonstrated expert bookbinding and trained apprentices.','从未学会技艺不能证明其 mastership。'),[Q('Mastership of bookbinding means?','expert command of the craft','a payment card','a meeting at lunchtime','mastership 指精通某种工艺。'),Q('What showed her skill?','clean joints and durable covers','unbound loose pages','a loud performance','作品接缝整洁且封面耐用，体现技艺。'),Q('Which suffix forms mastership?','-ship','-less','-al','master 加 -ship 构成状态或身份名词。','word-formation'),Q('What did she teach apprentices?','traditional bookbinding','how to measure a marlin','how to create a marsh','她把装帧工艺传授给学徒。')]);
P('masterwork','Masterwork combines master and work and means a work of exceptionally high artistic or technical quality.',C('masterwork.s1','工艺收藏','The cabinetmaker’s masterwork is a walnut desk whose precise joints have held firm for more than a century.','这位细木工的杰作是一张胡桃木书桌，精密接缝一百多年来仍然牢固。','The cabinetmaker’s masterwork / is a walnut desk / whose precise joints / have held firm for more than a century.','masterwork 作可数名词，指高水平的作品或成果。','精密工艺和长期耐用体现杰出质量。'),M('The curator called the badly warped, unfinished desk a masterwork despite its poor construction.','The curator called the carefully built, enduring desk a masterwork.','严重变形、未完成的作品不符合杰作评价。'),[Q('A masterwork is?','a work of exceptionally high quality','an ordinary unfinished draft','a payment network','masterwork 指技艺或艺术质量极高的作品。'),Q('What showed the desk’s quality?','precise joints that lasted over a century','a large markup on its price','a loud name on its masthead','接缝精密且历久牢固。'),Q('Which word is close in meaning to masterwork?','masterpiece','marshland','massacre','masterpiece 和 masterwork 都可指杰作。'),Q('The walnut desk was made by a?','cabinetmaker','marlin','mascot','例句中制作者是细木工。')]);
P('mastery','Mastery comes through French from master and means complete skill, knowledge, or control of a subject.',C('mastery.s1','语言学习','Her mastery of French allowed her to interpret the interview without relying on a written translation.','她精通法语，因此无需依赖书面翻译就能口译这场采访。','Her mastery of French / allowed her to interpret the interview / without relying / on a written translation.','mastery 作不可数名词，mastery of a skill 表示对技能的熟练掌握。','能无稿口译说明语言能力达到熟练程度。'),M('He demonstrated mastery of the language by being unable to understand a single sentence.','He demonstrated mastery of the language by interpreting the conversation accurately without notes.','完全无法理解与精通语言相矛盾。'),[Q('Mastery of French means?','complete skill or command of French','a brief introductory lesson only','a marriage to a French person','mastery 指熟练掌握。'),Q('What could she do because of her mastery?','interpret without a written translation','mass-produce a French dictionary','build a marshland','熟练法语使她能直接口译。'),Q('Which phrase is natural?','mastery of a language','mastery in a language only','a masterful of language','常说 mastery of a subject or skill。','collocation'),Q('Mastery is closest to?','expert command','loudness','marital status','expert command 表示熟练掌握。')]);
P('masthead','Masthead combines mast and head; it can mean the top of a ship’s mast or the publication section listing its name and staff.',[C('masthead.s1','航海传统','The lookout climbed to the masthead to inspect the rigging before the ship left the harbour.','船离开港口前，瞭望员爬到桅顶检查索具。','The lookout climbed / to the masthead / to inspect the rigging / before the ship left the harbour.','masthead 作名词可指桅杆的顶端。','高处检查桅索符合航海义 s1。'),C('masthead.s1','报刊版面','The newspaper’s masthead lists the editor, publisher, and address above the first page’s main stories.','报纸的刊头在首页主要新闻上方列出编辑、出版商和地址。','The newspaper’s masthead lists / the editor, publisher, and address / above the first page’s / main stories.','masthead 在出版语境可指刊名和编辑信息所在的刊头。','列出刊物名称与工作人员信息，符合该出版用法。'),C('masthead.s2','升至桅顶','The crew mastheaded the flag at sunrise so it could be seen from the harbour entrance.','船员在日出时把旗升到桅顶，使它从港口入口处也能看见。','The crew mastheaded the flag / at sunrise / so it could be seen / from the harbour entrance.','masthead 也可作动词，表示把某物升到桅顶或爬到桅顶。','旗帜被升到桅顶以供远处辨认。')],M('The masthead of the newspaper was the lowest paragraph at the back and contained no title or staff information.','The newspaper’s masthead appeared near the top and listed the publication name and staff.','刊头通常位于报刊版面上部，标出名称与工作人员信息。'),[Q('A ship’s masthead is?','the top of its mast','a low wet field','a marble toy','航海义 masthead 指桅杆顶端。'),Q('A newspaper masthead often lists?','the publication name and staff','the recipe for lunch','the mass of a ship','刊头包含刊名及编辑出版信息。'),Q('What did the crew masthead?','a flag','a manuscript','a mat','动词用法指把旗升到桅顶。'),Q('Where was the lookout before departure?','at the top of the mast','at the bottom of the marsh','inside the marketplace','瞭望员爬上桅顶检查索具。')]);
P('masticate','Masticate comes from Latin masticare, from Greek mastichan (“to chew”), and means to grind food with the teeth before swallowing.',C('masticate.s1','饮食说明','The dentist reminded the patient to masticate slowly on the unaffected side while the sore tooth healed.','牙医提醒患者在疼痛的牙齿痊愈期间，先用未受影响的一侧慢慢咀嚼。','The dentist reminded the patient / to masticate slowly / on the unaffected side / while the sore tooth healed.','masticate 作及物动词，语体较正式，宾语通常是食物。','牙齿把食物磨碎后再吞咽，符合 s1。'),M('The child masticated the soup by swallowing it whole without moving the jaw or using the teeth.','The child masticated the bread carefully before swallowing it.','不使用牙齿或下颌的吞咽不属于咀嚼。'),[Q('To masticate food is to?','chew it with the teeth','swallow it without chewing','mark it on a map','masticate 是正式词，意思是咀嚼。'),Q('Why did the patient chew on the unaffected side?','a sore tooth was healing','the dentist was measuring a mast','the patient had a marathon','牙痛期间避开患处咀嚼。'),Q('Which everyday word is closest to masticate?','chew','marry','massacre','chew 是 masticate 的常用近义词。'),Q('Masticate comes from a Greek root meaning?','to chew','to climb a mast','to make a market','词源与表示咀嚼的希腊词相关。')]);
P('mastodon','Mastodon was formed from Greek mastos (“breast”) and odous (“tooth”), referring to the shape of this extinct elephant-like animal’s teeth.',C('mastodon.s1','古生物展览','The museum displayed a mastodon tusk beside a reconstruction of the extinct animal that once lived in North America.','博物馆在一具复原的灭绝动物模型旁展示了一根乳齿象牙；这种动物曾生活在北美。','The museum displayed / a mastodon tusk / beside a reconstruction / of the extinct animal.','mastodon 作可数名词，指 Mammut 属已灭绝的象类动物。','牙齿化石与复原模型对应灭绝的乳齿象。'),M('The guide identified the mastodon as a living small bird with no teeth or tusks.','The guide identified the mastodon as an extinct elephant-like mammal with tusks.','mastodon 是灭绝的大型哺乳动物，不是无齿小鸟。'),[Q('A mastodon was an extinct?','elephant-like mammal','small fork-tailed bird','modern payment card','mastodon 指已灭绝的象类动物。'),Q('What did the museum display?','a mastodon tusk','a maraca and a mask','a mass-produced bottle','博物馆展出乳齿象牙。'),Q('Where did the animal once live, according to the example?','North America','a modern marketplace','the Moon','例句说这种动物曾生活在北美。'),Q('The word mastodon refers to the shape of its?','teeth','marshland','marital status','名称构词与牙齿形状有关。')]);
P('mat','Mat is an old word for a small piece of material used on a floor or under an object; as a verb it can mean become tangled into a dense mass.',[C('mat.s1','入口地垫','Visitors wiped their boots on the mat by the entrance before walking across the polished floor.','访客在入口旁的垫子上擦净靴子，再走过抛光地板。','Visitors wiped their boots / on the mat by the entrance / before walking / across the polished floor.','mat 作可数名词，指覆盖地面一小块区域的垫子。','入口垫用于擦鞋并保护地板。'),C('mat.s2','餐桌用品','She placed a woven mat under the hot serving dish to protect the wooden table.','她在热菜盘下垫了一块编织餐垫，以保护木桌。','She placed a woven mat / under the hot serving dish / to protect / the wooden table.','mat 也可指盘子或杯子下方的小垫子。','餐垫隔开热盘和桌面，符合 s2。'),C('mat.s3','毛发打结','Without regular brushing, the dog’s long fur began to mat around the collar.','由于没有定期梳理，狗脖圈周围的长毛开始缠结成团。','Without regular brushing / the dog’s long fur began to mat / around the collar.','mat 作不及物动词，表示毛发或纤维纠缠成厚团。','毛发缠结在脖圈周围，符合 s3。')],M('The dog’s fur matted smoothly into separate silky strands without tangling into a clump.','The dog’s fur matted into a dense tangle around the collar.','形成顺滑分离发丝并非 mat 作动词的缠结义。'),[Q('A mat by the door is used to?','wipe or catch dirt from shoes','hold a ship’s mast','measure a mass','入口地垫用来擦鞋或接住泥土。'),Q('What was placed under the serving dish?','a woven mat','a manuscript','a marlin','餐盘下放了隔热餐垫。'),Q('When fur mats, it?','tangles into a dense mass','becomes a payment card','turns into a marble statue','mat 作动词表示缠结成团。'),Q('Which phrase is natural?','a mat under a glass','a mat of marital status','matly floor','mat 可放在盘子或杯子下保护桌面。','collocation')]);
P('match','Match has several histories and uses: a contest, a fire-lighting stick, an equal or suitable partner, to correspond, or to set rivals against each other.',[C('match.s1','体育比赛','The final match ended in a draw after both teams scored once in the last ten minutes.','两队在最后十分钟各进一球后，决赛以平局结束。','The final match ended in a draw / after both teams scored once / in the last ten minutes.','match 作名词指两名或两队之间的比赛。','两队在赛事中竞争，符合 s1。'),C('match.s2','点火用品','He struck a match and lit the camping stove after checking that the area was clear of dry grass.','确认周围没有干草后，他划燃一根火柴，点着了露营炉。','He struck a match / and lit the camping stove / after checking / that the area was clear of dry grass.','match 作可数名词可指带易燃头、摩擦后点火的小木棒。','火柴用于点燃露营炉，符合 s2。'),C('match.s3','实力相当者','The young champion finally met her match in a veteran player who had won three national titles.','这位年轻冠军终于遇到了旗鼓相当的对手——一位曾赢得三次全国冠军的老将。','The young champion finally met her match / in a veteran player / who had won / three national titles.','meet one’s match 指遇到能力相当甚至更强的人或对手。','老将实力与冠军相当，符合 s3。'),C('match.s4','颜色协调','The curtains match the blue cushions, giving the sitting room a calm, coordinated appearance.','窗帘与蓝色靠垫相配，让客厅看起来平和协调。','The curtains match / the blue cushions / giving the sitting room / a calm, coordinated appearance.','match 作动词可表示颜色、样式相同或相协调。','窗帘和靠垫颜色搭配，符合 s4。'),C('match.s5','安排对赛','The league matched the two undefeated clubs against each other in the semifinal.','联赛在半决赛中安排两支未尝败绩的俱乐部相互较量。','The league matched / the two undefeated clubs / against each other / in the semifinal.','match A against B 表示安排两方相互比赛。','联赛把两支球队配对交锋，符合 s5。')],M('She struck a match to light the stove by rubbing a paper map against the table.','She struck a wooden match against its rough strip to light the camping stove.','点火用 match 是火柴，不是地图纸。'),[Q('A final match is?','a contest between teams or players','a small instrument for chewing','a market price increase','match 可指体育比赛。'),Q('What is a match used to light a stove?','a short stick with an igniting tip','a master’s degree','a piece of wet marshland','火柴摩擦后可点火。'),Q('To meet your match is to?','encounter someone of equal ability','lose your luggage','find a marital status form','习语指遇到旗鼓相当的对手。'),Q('If curtains match cushions, they?','are similar or go well together','compete in a final','light a stove','match 可表示颜色或样式相配。')]);
P('matching','Matching is formed from match plus -ing and describes items that coordinate in colour or style, or that are exactly the same.',[C('matching.s1','家居搭配','The set includes matching curtains and cushions in the same blue-and-white pattern.','这套家居用品包括同一蓝白图案、彼此协调的窗帘和靠垫。','The set includes / matching curtains and cushions / in the same blue-and-white pattern.','matching 作形容词，表示颜色、图案或风格相配。','两种用品采用同一图案，符合 s1。'),C('matching.s2','身份核验','The clerk checked that the two matching numbers on the form and the receipt were exactly the same.','办事员核对表格和收据上的两个对应号码是否完全一致。','The clerk checked / that the two matching numbers / on the form and receipt / were exactly the same.','matching 也可表示相同或一一对应。','表格和收据号码完全一致，符合 s2。')],M('The clerk accepted the documents as matching even though their reference numbers were completely different.','The clerk accepted the documents as matching because their reference numbers were identical.','号码完全不同就不能称为完全一致。'),[Q('Matching curtains and cushions?','coordinate in colour or pattern','are made of marble','belong to a marathon','matching 可表示协调搭配。'),Q('Matching numbers on two documents are?','exactly the same or corresponding','both very loud','written only in a manuscript','matching 也可表示完全相同或对应。'),Q('What pattern did the set use?','blue and white','maroon and lunar','marsh and maple','窗帘和靠垫采用蓝白相同图案。'),Q('Which sentence is natural?','They wore matching coats.','They wore matchingly coats.','They matchings wore coats.','matching 可作形容词修饰 coats。','grammar')]);
P('matchless','Matchless combines match and -less and means without an equal, exceptionally good, or never surpassed in its kind.',[C('matchless.s1','艺术评价','The singer’s matchless control of pitch made even the quietest passage carry across the concert hall.','这位歌手对音高无与伦比的掌控力，让最轻柔的乐段也能传遍音乐厅。','The singer’s matchless control of pitch / made even the quietest passage / carry across the concert hall.','matchless 作形容词，表示没有可相比的同类或对手。','无可比拟的音准控制力符合 s1。'),C('matchless.s2','技艺记录','Her matchless performance set a record that no other team had achieved in the competition’s history.','她们出众的表现创造了一项赛事史上无人达到的纪录。','Her matchless performance / set a record / that no other team / had achieved in the competition’s history.','matchless 也可强调技艺或成就空前、无人企及。','从未有团队达到的纪录符合 s2。')],M('The judges called the performance matchless even though several other singers performed exactly as well or better.','The judges called the performance matchless because no rival equalled the singer’s control and expression.','已有多位表现相当或更好者，就不能说无人能比。'),[Q('A matchless singer has?','no equal in the relevant skill','a matching uniform','a lost manuscript','matchless 表示无与伦比。'),Q('What was unprecedented in the example?','the record no other team had reached','the singer’s lunch break','the colour of the stage mat','她们创造了无人达到的纪录。'),Q('Which suffix means “without”?','-less','-ful','-ship','match 加 -less 表示没有匹敌者。','word-formation'),Q('Which phrase is natural?','matchless beauty','matchlessly beauty','a matchless of beauty','matchless 可作形容词修饰 beauty。','grammar')]);
P('matchstick','Matchstick combines match and stick and means the small wooden stick of a match, especially the stick with an igniting head.',C('matchstick.s1','手工模型','The children glued matchsticks together to build a small bridge model for their science display.','孩子们把火柴棍粘在一起，为科学展示制作一座小桥模型。','The children glued / matchsticks together / to build a small bridge model / for their science display.','matchstick 作可数名词，复数 matchsticks 指火柴棍。','火柴棍被用作手工模型材料，符合 s1。'),M('The model used matchsticks even though the children built it entirely from full-sized steel beams.','The model used matchsticks, small wooden sticks arranged and glued together.','全尺寸钢梁不属于火柴棍。'),[Q('A matchstick is?','a small stick used in a match','a large ship’s mast','a marble carving','matchstick 指火柴的小木棍。'),Q('What did the children make from them?','a small bridge model','a mass of wet clay','a marital certificate','孩子们用火柴棍搭建桥梁模型。'),Q('Which words form matchstick?','match + stick','master + ship','mass + if','matchstick 是 match 和 stick 的复合词。','word-formation'),Q('Which spelling is correct?','matchsticks','matchstickses','match-stickses','matchstick 的复数为 matchsticks。','plural')]);

})();
